 "create or replace function public.categories_create(\n  p_name text,\n  p_type category_type,\n  p_icon text default null,\n  p_color text default null\n)\nreturns public.categories\nlanguage plpgsql\nas $$\ndeclare\n  v_category public.categories;\nbegin\n  if exists (\n    select 1 from public.categories\n    where owner_id = auth.uid()\n      and type = p_type\n      and status = 'active'\n      and lower(name) = lower(p_name)\n  ) then\n    raise exception 'Category with this name already exists.' using errcode = 'P0001';\n  end if;\n\n  insert into public.categories (owner_id, name, type, icon, color, is_default, status)\n  values (auth.uid(), p_name, p_type, p_icon, p_color, false, 'active')\n  returning * into v_category;\n\n  return v_category;\nend;\n$$",
 "grant execute on function public.categories_create(text, category_type, text, text) to authenticated",
 "create or replace function public.transactions_create(\n  p_wallet_id uuid,\n  p_amount numeric,\n  p_type transaction_type,\n  p_category_id uuid default null,\n  p_description text default null,\n  p_date timestamptz default now(),\n  p_attachments text[] default '{}',\n  p_tags text[] default '{}',\n  p_to_wallet_id uuid default null,\n  p_bill_id uuid default null,\n  p_service_fee numeric default 0,\n  p_create_bill_for_fee boolean default false\n)\nreturns public.transactions\nlanguage plpgsql\nas $$\ndeclare\n  v_wallet public.wallets;\n  v_to_wallet public.wallets;\n  v_immediate_fee numeric := 0;\n  v_total_deduction numeric;\n  v_fee_deducted boolean := false;\n  v_txn public.transactions;\n  v_fee_due_date timestamptz;\n  v_fee_txn public.transactions;\nbegin\n  select * into v_wallet from public.wallets\n  where id = p_wallet_id and owner_id = auth.uid() and status = 'active';\n  if not found then\n    raise exception 'Wallet not found or inactive.' using errcode = 'P0002';\n  end if;\n\n  if p_type = 'transfer' then\n    if p_to_wallet_id is null then\n      raise exception 'Destination wallet required for transfers.' using errcode = 'P0001';\n    end if;\n    if p_wallet_id = p_to_wallet_id then\n      raise exception 'Cannot transfer to the same wallet.' using errcode = 'P0001';\n    end if;\n    select * into v_to_wallet from public.wallets\n    where id = p_to_wallet_id and owner_id = auth.uid() and status = 'active';\n    if not found then\n      raise exception 'Destination wallet not found or inactive.' using errcode = 'P0002';\n    end if;\n  end if;\n\n  v_immediate_fee := case when not p_create_bill_for_fee and p_service_fee > 0 then p_service_fee else 0 end;\n  v_total_deduction := case when p_type = 'transfer' then p_amount + v_immediate_fee else p_amount end;\n\n  if p_type in ('expense', 'transfer') and v_wallet.balance < v_total_deduction then\n    raise exception 'Insufficient wallet balance for transaction%',\n      case when v_immediate_fee > 0 then ' and service fee.' else '.' end\n      using errcode = 'P0001';\n  end if;\n\n  v_fee_deducted := (p_type = 'transfer' and p_service_fee > 0 and not p_create_bill_for_fee);\n\n  insert into public.transactions (\n    owner_id, wallet_id, category_id, amount, type, description, date,\n    attachments, tags, to_wallet_id, bill_id, service_fee, service_fee_deducted, status\n  ) values (\n    auth.uid(), p_wallet_id, p_category_id, p_amount, p_type, p_description, p_date,\n    p_attachments, p_tags, p_to_wallet_id, p_bill_id, p_service_fee, v_fee_deducted, 'completed'\n  )\n  returning * into v_txn;\n\n  if p_type = 'income' then\n    update public.wallets set balance = balance + p_amount where id = p_wallet_id;\n  elsif p_type = 'expense' then\n    update public.wallets set balance = balance - p_amount where id = p_wallet_id;\n  elsif p_type = 'transfer' then\n    update public.wallets set balance = balance - (p_amount + case when v_fee_deducted then p_service_fee else 0 end)\n      where id = p_wallet_id;\n    update public.wallets set balance = balance + p_amount where id = p_to_wallet_id;\n  end if;\n\n  if p_bill_id is not null then\n    update public.bills\n    set payment_status = 'paid', paid_amount = p_amount, last_paid_date = v_txn.date\n    where id = p_bill_id and owner_id = auth.uid();\n  end if;\n\n  if p_create_bill_for_fee and p_service_fee > 0 then\n    v_fee_due_date := v_txn.date + interval '1 day';\n\n    insert into public.transactions (\n      owner_id, wallet_id, amount, type, description, date, attachments, tags, status\n    ) values (\n      auth.uid(), p_wallet_id, p_service_fee, 'expense',\n      format('Service fee for transfer of %s', p_amount), v_fee_due_date, '{}', '{}', 'pending'\n    )\n    returning * into v_fee_txn;\n\n    insert into public.bills (\n      owner_id, name, amount, due_date, is_recurring, wallet_id, reminder,\n      payment_status, notes, status, transaction_id\n    ) values (\n      auth.uid(), 'Transfer Service Fee', p_service_fee, v_fee_due_date, false, p_wallet_id, false,\n      'unpaid', format('Service fee for transfer transaction ID: %s', v_txn.id), 'active', v_fee_txn.id\n    );\n  end if;\n\n  return v_txn;\nend;\n$$",
 "grant execute on function public.transactions_create(\n  uuid, numeric, transaction_type, uuid, text, timestamptz, text[], text[], uuid, uuid, numeric, boolean\n) to authenticated",
 "create or replace function public.transactions_update(\n  p_id uuid,\n  p_category_id uuid default null,\n  p_description text default null,\n  p_date timestamptz default null,\n  p_attachments text[] default null,\n  p_tags text[] default null,\n  p_status transaction_status default null\n)\nreturns public.transactions\nlanguage plpgsql\nas $$\ndeclare\n  v_txn public.transactions;\nbegin\n  update public.transactions\n  set\n    category_id = coalesce(p_category_id, category_id),\n    description = coalesce(p_description, description),\n    date = coalesce(p_date, date),\n    attachments = coalesce(p_attachments, attachments),\n    tags = coalesce(p_tags, tags),\n    status = coalesce(p_status, status)\n  where id = p_id and owner_id = auth.uid()\n  returning * into v_txn;\n\n  if not found then\n    raise exception 'Transaction not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  return v_txn;\nend;\n$$",
 "grant execute on function public.transactions_update(uuid, uuid, text, timestamptz, text[], text[], transaction_status) to authenticated",
 "create or replace function public.transactions_delete(p_id uuid)\nreturns void\nlanguage plpgsql\nas $$\ndeclare\n  v_txn public.transactions;\nbegin\n  select * into v_txn from public.transactions\n  where id = p_id and owner_id = auth.uid();\n\n  if not found then\n    raise exception 'Transaction not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  if v_txn.status <> 'completed' then\n    raise exception 'Can only delete completed transactions.' using errcode = 'P0001';\n  end if;\n\n  if v_txn.type = 'income' then\n    update public.wallets set balance = balance - v_txn.amount where id = v_txn.wallet_id;\n  elsif v_txn.type = 'expense' then\n    update public.wallets set balance = balance + v_txn.amount where id = v_txn.wallet_id;\n  elsif v_txn.type = 'transfer' and v_txn.to_wallet_id is not null then\n    update public.wallets\n    set balance = balance + v_txn.amount + case when v_txn.service_fee_deducted then v_txn.service_fee else 0 end\n    where id = v_txn.wallet_id;\n    update public.wallets set balance = balance - v_txn.amount where id = v_txn.to_wallet_id;\n  end if;\n\n  delete from public.transactions where id = p_id;\nend;\n$$",
 "grant execute on function public.transactions_delete(uuid) to authenticated",
 "create or replace function public.transactions_bulk_import(\n  p_wallet_id uuid,\n  p_rows jsonb\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_wallet public.wallets;\n  v_inserted integer;\n  v_income_total numeric;\n  v_expense_total numeric;\nbegin\n  select * into v_wallet from public.wallets\n  where id = p_wallet_id and owner_id = auth.uid() and status = 'active';\n  if not found then\n    raise exception 'Wallet not found or inactive.' using errcode = 'P0002';\n  end if;\n\n  with rows as (\n    select *\n    from jsonb_to_recordset(p_rows) as r(\n      date timestamptz,\n      amount numeric,\n      type transaction_type,\n      description text,\n      tags text[],\n      category_id uuid\n    )\n  ),\n  inserted as (\n    insert into public.transactions (\n      owner_id, wallet_id, amount, type, description, date, tags, category_id, attachments, status\n    )\n    select auth.uid(), p_wallet_id, amount, type, description, date,\n           coalesce(tags, '{}'), category_id, '{}', 'completed'\n    from rows\n    returning amount, type\n  )\n  select\n    count(*),\n    coalesce(sum(amount) filter (where type = 'income'), 0),\n    coalesce(sum(amount) filter (where type = 'expense'), 0)\n  into v_inserted, v_income_total, v_expense_total\n  from inserted;\n\n  update public.wallets\n  set balance = balance + v_income_total - v_expense_total\n  where id = p_wallet_id;\n\n  return jsonb_build_object('imported', v_inserted);\nend;\n$$",
 "grant execute on function public.transactions_bulk_import(uuid, jsonb) to authenticated",
 "create or replace function public.bills_create(\n  p_name text,\n  p_amount numeric,\n  p_due_date timestamptz,\n  p_is_recurring boolean,\n  p_type bill_type,\n  p_category_id uuid default null,\n  p_recurring_frequency recurring_frequency default null,\n  p_wallet_id uuid default null,\n  p_reminder boolean default true,\n  p_reminder_days integer default 3,\n  p_notes text default null\n)\nreturns public.bills\nlanguage plpgsql\nas $$\ndeclare\n  v_bill public.bills;\n  v_txn public.transactions;\nbegin\n  if p_is_recurring and p_recurring_frequency is null then\n    raise exception 'Recurring frequency required for recurring bills.' using errcode = 'P0001';\n  end if;\n\n  insert into public.bills (\n    owner_id, name, amount, category_id, due_date, is_recurring, type,\n    recurring_frequency, wallet_id, reminder, reminder_days, notes,\n    payment_status, status\n  ) values (\n    auth.uid(), p_name, p_amount, p_category_id, p_due_date, p_is_recurring, p_type,\n    p_recurring_frequency, p_wallet_id, p_reminder, p_reminder_days, p_notes,\n    'unpaid', 'active'\n  )\n  returning * into v_bill;\n\n  if p_wallet_id is not null then\n    insert into public.transactions (\n      owner_id, wallet_id, category_id, amount, type, description, date,\n      attachments, tags, bill_id, status\n    ) values (\n      auth.uid(), p_wallet_id, p_category_id, p_amount, 'expense',\n      format('Bill: %s', p_name), p_due_date, '{}', '{}', v_bill.id, 'pending'\n    )\n    returning * into v_txn;\n\n    update public.bills set transaction_id = v_txn.id where id = v_bill.id\n    returning * into v_bill;\n  end if;\n\n  return v_bill;\nend;\n$$",
 "grant execute on function public.bills_create(\n  text, numeric, timestamptz, boolean, bill_type, uuid, recurring_frequency, uuid, boolean, integer, text\n) to authenticated",
 "create or replace function public.bills_mark_paid(\n  p_id uuid,\n  p_paid_amount numeric default null,\n  p_paid_date timestamptz default null,\n  p_idempotency_key text default null\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_bill public.bills;\n  v_amount_paid numeric;\n  v_payment_date timestamptz;\n  v_wallet public.wallets;\n  v_payment_status bill_payment_status;\n  v_obligation public.obligations;\n  v_new_remaining numeric;\n  v_new_paid_installments integer;\n  v_new_obl_status obligation_status;\n  v_next_due_date timestamptz;\n  v_next_bill public.bills;\n  v_next_txn public.transactions;\nbegin\n  if p_idempotency_key is not null and exists (\n    select 1 from public.transactions\n    where owner_id = auth.uid()\n      and idempotency_key = p_idempotency_key\n      and created_at >= now() - interval '24 hours'\n      and status = 'completed'\n  ) then\n    return jsonb_build_object(\n      'id', p_id,\n      'message', 'Duplicate payment request detected. Original payment processed.'\n    );\n  end if;\n\n  select * into v_bill from public.bills where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Bill not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  v_amount_paid := coalesce(p_paid_amount, v_bill.amount);\n  v_payment_date := coalesce(p_paid_date, now());\n\n  if v_bill.wallet_id is not null then\n    update public.wallets\n    set balance = balance - v_amount_paid\n    where id = v_bill.wallet_id and owner_id = auth.uid()\n    returning * into v_wallet;\n\n    if not found then\n      raise exception 'Linked wallet not found or inactive.' using errcode = 'P0002';\n    end if;\n\n    if v_wallet.balance < 0 then\n      raise exception 'Insufficient wallet balance to pay this bill.' using errcode = 'P0001';\n    end if;\n  end if;\n\n  v_payment_status := case when v_amount_paid >= v_bill.amount then 'paid' else 'partial' end;\n\n  if v_bill.transaction_id is not null then\n    update public.transactions\n    set status = 'completed', amount = v_amount_paid, date = v_payment_date,\n        idempotency_key = coalesce(p_idempotency_key, idempotency_key)\n    where id = v_bill.transaction_id;\n  end if;\n\n  if v_bill.obligation_id is not null then\n    select * into v_obligation from public.obligations where id = v_bill.obligation_id;\n    if found and v_obligation.status not in ('settled', 'archived') then\n      v_new_remaining := round(greatest(0, v_obligation.remaining_balance - v_amount_paid)::numeric, 2);\n      v_new_paid_installments := case when v_obligation.is_installment\n        then v_obligation.paid_installments + 1 else v_obligation.paid_installments end;\n      v_new_obl_status := case\n        when v_new_remaining <= 0 then 'settled'\n        when v_new_paid_installments > 0 then 'partially_paid'\n        else 'active'\n      end;\n\n      update public.obligations\n      set remaining_balance = v_new_remaining,\n          paid_installments = v_new_paid_installments,\n          status = v_new_obl_status\n      where id = v_obligation.id;\n    end if;\n  end if;\n\n  if v_bill.is_recurring and v_bill.recurring_frequency is not null then\n    v_next_due_date := public.calculate_next_due_date(v_bill.due_date, v_bill.recurring_frequency);\n\n    insert into public.bills (\n      owner_id, name, amount, category_id, due_date, is_recurring, recurring_frequency,\n      wallet_id, reminder, reminder_days, notes, payment_status, status, parent_bill_id, type\n    ) values (\n      v_bill.owner_id, v_bill.name, v_bill.amount, v_bill.category_id, v_next_due_date,\n      v_bill.is_recurring, v_bill.recurring_frequency, v_bill.wallet_id, v_bill.reminder,\n      v_bill.reminder_days, v_bill.notes, 'unpaid', 'active',\n      coalesce(v_bill.parent_bill_id, v_bill.id), v_bill.type\n    )\n    returning * into v_next_bill;\n\n    if v_bill.wallet_id is not null then\n      insert into public.transactions (\n        owner_id, wallet_id, category_id, amount, type, description, date,\n        attachments, tags, bill_id, status\n      ) values (\n        v_bill.owner_id, v_bill.wallet_id, v_bill.category_id, v_bill.amount, 'expense',\n        format('Bill: %s', v_bill.name), v_next_due_date, '{}', '{}', v_next_bill.id, 'pending'\n      )\n      returning * into v_next_txn;\n\n      update public.bills set transaction_id = v_next_txn.id where id = v_next_bill.id;\n    end if;\n  end if;\n\n  update public.bills\n  set paid_amount = v_amount_paid, last_paid_date = v_payment_date, payment_status = v_payment_status\n  where id = p_id;\n\n  return jsonb_build_object(\n    'billId', p_id,\n    'amountPaid', v_amount_paid,\n    'nextDueDate', v_next_due_date,\n    'isRecurring', v_bill.is_recurring\n  );\nend;\n$$",
 "grant execute on function public.bills_mark_paid(uuid, numeric, timestamptz, text) to authenticated",
 "create or replace function public.bills_get_overdue()\nreturns setof public.bills\nlanguage plpgsql\nas $$\nbegin\n  update public.bills\n  set payment_status = 'overdue'\n  where owner_id = auth.uid()\n    and status = 'active'\n    and payment_status in ('unpaid', 'partial')\n    and due_date < date_trunc('day', now());\n\n  return query\n  select * from public.bills\n  where owner_id = auth.uid()\n    and status = 'active'\n    and payment_status = 'overdue'\n  order by due_date asc;\nend;\n$$",
 "grant execute on function public.bills_get_overdue() to authenticated",
 "create or replace function public.bills_summary()\nreturns jsonb\nlanguage plpgsql\nstable\nas $$\ndeclare\n  v_total_bills integer;\n  v_paid_bills integer;\n  v_unpaid_bills integer;\n  v_overdue_bills integer;\n  v_partial_bills integer;\n  v_recurring_bills integer;\n  v_total_amount_due numeric;\n  v_upcoming_amount numeric;\n  v_overdue_amount numeric;\n  v_total_wallet_balance numeric;\nbegin\n  select\n    count(*),\n    count(*) filter (where payment_status = 'paid'),\n    count(*) filter (where payment_status = 'unpaid'),\n    count(*) filter (where payment_status = 'overdue'),\n    count(*) filter (where payment_status = 'partial'),\n    count(*) filter (where is_recurring)\n  into v_total_bills, v_paid_bills, v_unpaid_bills, v_overdue_bills, v_partial_bills, v_recurring_bills\n  from public.bills\n  where owner_id = auth.uid() and status = 'active';\n\n  select\n    coalesce(sum(amount), 0),\n    coalesce(sum(amount) filter (where due_date > now()), 0),\n    coalesce(sum(amount) filter (where due_date < now()), 0)\n  into v_total_amount_due, v_upcoming_amount, v_overdue_amount\n  from public.bills\n  where owner_id = auth.uid() and status = 'active'\n    and payment_status in ('unpaid', 'overdue', 'partial');\n\n  select coalesce(sum(balance), 0) into v_total_wallet_balance\n  from public.wallets where owner_id = auth.uid() and status = 'active';\n\n  return jsonb_build_object(\n    'totalBills', v_total_bills,\n    'paidBills', v_paid_bills,\n    'unpaidBills', v_unpaid_bills,\n    'overdueBills', v_overdue_bills,\n    'partialBills', v_partial_bills,\n    'recurringBills', v_recurring_bills,\n    'totalAmountDue', v_total_amount_due,\n    'upcomingAmount', v_upcoming_amount,\n    'overdueAmount', v_overdue_amount,\n    'totalWalletBalance', v_total_wallet_balance,\n    'disposableIncome', v_total_wallet_balance - v_total_amount_due,\n    'summary', jsonb_build_object(\n      'message', format('You have %s unpaid bills totaling ₱%s',\n        v_unpaid_bills + v_overdue_bills, to_char(v_total_amount_due, 'FM999999990.00'))\n    )\n  );\nend;\n$$",
 "grant execute on function public.bills_summary() to authenticated",
 "create or replace function public.budget_calculate_spent(\n  p_owner uuid,\n  p_category_id uuid,\n  p_start timestamptz,\n  p_end timestamptz\n)\nreturns numeric\nlanguage sql\nstable\nas $$\n  select coalesce(sum(amount), 0)\n  from public.transactions\n  where owner_id = p_owner\n    and type = 'expense'\n    and status = 'completed'\n    and date >= p_start and date <= p_end\n    and (p_category_id is null or category_id = p_category_id);\n$$",
 "create or replace function public.budgets_create(\n  p_name text,\n  p_amount numeric,\n  p_period budget_period,\n  p_start_date timestamptz,\n  p_category_id uuid default null,\n  p_end_date timestamptz default null,\n  p_alert_threshold numeric default 80\n)\nreturns public.budgets\nlanguage plpgsql\nas $$\ndeclare\n  v_end timestamptz;\n  v_budget public.budgets;\nbegin\n  v_end := coalesce(p_end_date, case p_period\n    when 'daily' then p_start_date + interval '1 day'\n    when 'weekly' then p_start_date + interval '7 days'\n    when 'monthly' then p_start_date + interval '1 month'\n    when 'yearly' then p_start_date + interval '1 year'\n  end);\n\n  insert into public.budgets (\n    owner_id, category_id, name, amount, spent, period, start_date, end_date,\n    alert_threshold, status\n  ) values (\n    auth.uid(), p_category_id, p_name, p_amount, 0, p_period, p_start_date, v_end,\n    coalesce(p_alert_threshold, 80), 'active'\n  )\n  returning * into v_budget;\n\n  return v_budget;\nend;\n$$",
 "grant execute on function public.budgets_create(text, numeric, budget_period, timestamptz, uuid, timestamptz, numeric) to authenticated",
 "create or replace function public.budgets_list(\n  p_page integer default 0,\n  p_limit integer default 20,\n  p_category_id uuid default null,\n  p_period budget_period default null,\n  p_status budget_status default 'active'\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_total integer;\n  v_items jsonb;\nbegin\n  select count(*) into v_total\n  from public.budgets\n  where owner_id = auth.uid()\n    and (p_category_id is null or category_id = p_category_id)\n    and (p_period is null or period = p_period)\n    and status = p_status;\n\n  with page as (\n    select * from public.budgets\n    where owner_id = auth.uid()\n      and (p_category_id is null or category_id = p_category_id)\n      and (p_period is null or period = p_period)\n      and status = p_status\n    order by start_date desc\n    offset p_page * p_limit limit p_limit\n  ),\n  refreshed as (\n    update public.budgets b\n    set spent = public.budget_calculate_spent(b.owner_id, b.category_id, b.start_date, b.end_date),\n        status = case\n          when public.budget_calculate_spent(b.owner_id, b.category_id, b.start_date, b.end_date) >= b.amount\n          then 'exceeded' else b.status end\n    from page\n    where b.id = page.id\n    returning b.*\n  )\n  select coalesce(jsonb_agg(to_jsonb(refreshed)), '[]'::jsonb) into v_items from refreshed;\n\n  return jsonb_build_object(\n    'items', v_items,\n    'totalPages', ceil(v_total::numeric / greatest(p_limit, 1)),\n    'currentPage', p_page,\n    'totalItems', v_total\n  );\nend;\n$$",
 "grant execute on function public.budgets_list(integer, integer, uuid, budget_period, budget_status) to authenticated",
 "create or replace function public.budgets_get_current(p_period budget_period default null)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_items jsonb;\nbegin\n  with current_budgets as (\n    select * from public.budgets\n    where owner_id = auth.uid()\n      and status in ('active', 'exceeded')\n      and start_date <= now() and end_date >= now()\n      and (p_period is null or period = p_period)\n  ),\n  refreshed as (\n    update public.budgets b\n    set spent = public.budget_calculate_spent(b.owner_id, b.category_id, b.start_date, b.end_date),\n        status = case\n          when public.budget_calculate_spent(b.owner_id, b.category_id, b.start_date, b.end_date) >= b.amount\n          then 'exceeded' else b.status end\n    from current_budgets\n    where b.id = current_budgets.id\n    returning b.*\n  )\n  select coalesce(jsonb_agg(to_jsonb(refreshed)), '[]'::jsonb) into v_items from refreshed;\n\n  return jsonb_build_object('items', v_items, 'totalBudgets', jsonb_array_length(v_items));\nend;\n$$",
 "grant execute on function public.budgets_get_current(budget_period) to authenticated",
 "create or replace function public.budgets_check_status(p_id uuid)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_budget public.budgets;\n  v_spent numeric;\n  v_remaining numeric;\n  v_percentage numeric;\n  v_is_over boolean;\n  v_is_near boolean;\nbegin\n  select * into v_budget from public.budgets where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Budget not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  v_spent := public.budget_calculate_spent(v_budget.owner_id, v_budget.category_id, v_budget.start_date, v_budget.end_date);\n  v_remaining := v_budget.amount - v_spent;\n  v_percentage := case when v_budget.amount > 0 then (v_spent / v_budget.amount) * 100 else 0 end;\n  v_is_over := v_spent >= v_budget.amount;\n  v_is_near := v_percentage >= coalesce(v_budget.alert_threshold, 80);\n\n  update public.budgets\n  set spent = v_spent, status = case when v_is_over then 'exceeded' else status end\n  where id = p_id\n  returning * into v_budget;\n\n  return jsonb_build_object(\n    'budget', to_jsonb(v_budget),\n    'spent', v_spent,\n    'remaining', v_remaining,\n    'percentageUsed', round(v_percentage, 2),\n    'isOverBudget', v_is_over,\n    'isNearThreshold', v_is_near\n  );\nend;\n$$",
 "grant execute on function public.budgets_check_status(uuid) to authenticated",
 "create or replace function public.budgets_rollover(p_budget_id uuid)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_budget public.budgets;\n  v_remaining numeric;\n  v_next_start timestamptz;\n  v_next_end timestamptz;\n  v_new_budget public.budgets;\nbegin\n  select * into v_budget from public.budgets where id = p_budget_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Budget not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  v_remaining := v_budget.amount - coalesce(v_budget.spent, 0);\n  if v_remaining <= 0 then\n    raise exception 'No remaining budget to rollover.' using errcode = 'P0001';\n  end if;\n\n  v_next_start := v_budget.end_date + interval '1 day';\n  v_next_end := case v_budget.period\n    when 'daily' then v_next_start + interval '1 day'\n    when 'weekly' then v_next_start + interval '7 days'\n    when 'monthly' then v_next_start + interval '1 month'\n    when 'yearly' then v_next_start + interval '1 year'\n  end;\n\n  insert into public.budgets (\n    owner_id, category_id, name, amount, spent, period, start_date, end_date,\n    alert_threshold, status\n  ) values (\n    v_budget.owner_id, v_budget.category_id, v_budget.name || ' (Rolled Over)',\n    v_budget.amount + v_remaining, 0, v_budget.period, v_next_start, v_next_end,\n    v_budget.alert_threshold, 'active'\n  )\n  returning * into v_new_budget;\n\n  return jsonb_build_object(\n    'previousBudgetId', v_budget.id,\n    'newBudgetId', v_new_budget.id,\n    'rolledOverAmount', v_remaining,\n    'newBudgetAmount', v_new_budget.amount,\n    'previousPeriod', jsonb_build_object(\n      'startDate', v_budget.start_date, 'endDate', v_budget.end_date,\n      'spent', v_budget.spent, 'remaining', v_remaining\n    ),\n    'newPeriod', jsonb_build_object(\n      'startDate', v_next_start, 'endDate', v_next_end, 'budgetAmount', v_new_budget.amount\n    )\n  );\nend;\n$$",
 "grant execute on function public.budgets_rollover(uuid) to authenticated",
 "create or replace function public.budgets_performance()\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_budgets jsonb;\n  v_total_budgeted numeric := 0;\n  v_total_spent numeric := 0;\n  v_first_start timestamptz;\n  v_first_end timestamptz;\n  v_days_elapsed integer;\n  v_days_remaining integer;\n  v_overall_burn_rate numeric;\nbegin\n  with current_budgets as (\n    select b.*, c.name as category_name\n    from public.budgets b\n    left join public.categories c on c.id = b.category_id\n    where b.owner_id = auth.uid()\n      and b.status in ('active', 'exceeded')\n      and b.start_date <= now() and b.end_date >= now()\n  ),\n  metrics as (\n    select\n      cb.id as budget_id, cb.name, coalesce(cb.category_name, 'Uncategorized') as category_name,\n      cb.amount,\n      public.budget_calculate_spent(cb.owner_id, cb.category_id, cb.start_date, cb.end_date) as spent,\n      ceil(extract(epoch from (cb.end_date - cb.start_date)) / 86400)::integer as total_days,\n      ceil(extract(epoch from (now() - cb.start_date)) / 86400)::integer as days_elapsed,\n      cb.start_date, cb.end_date\n    from current_budgets cb\n  )\n  select\n    coalesce(jsonb_agg(jsonb_build_object(\n      'budgetId', budget_id, 'name', name, 'categoryName', category_name,\n      'amount', amount, 'spent', spent, 'remaining', amount - spent,\n      'percentageUsed', case when amount > 0 then (spent / amount) * 100 else 0 end,\n      'burnRate', round(case when total_days > 0 and days_elapsed > 0\n        then (spent / nullif((amount / total_days) * days_elapsed, 0)) * 100 else 0 end, 2),\n      'daysElapsed', days_elapsed, 'daysRemaining', total_days - days_elapsed,\n      'status', case\n        when total_days > 0 and days_elapsed > 0\n          and (spent / nullif((amount / total_days) * days_elapsed, 0)) * 100 > 100 then 'OverBudget'\n        when total_days > 0 and days_elapsed > 0\n          and (spent / nullif((amount / total_days) * days_elapsed, 0)) * 100 < 100 then 'UnderBudget'\n        else 'OnTrack' end\n    )), '[]'::jsonb),\n    coalesce(sum(amount), 0), coalesce(sum(spent), 0),\n    min(start_date), max(end_date)\n  into v_budgets, v_total_budgeted, v_total_spent, v_first_start, v_first_end\n  from metrics;\n\n  if v_first_start is null then\n    return jsonb_build_object(\n      'message', 'No active budgets for this period', 'budgets', '[]'::jsonb,\n      'overallBurnRate', 0, 'totalBudgeted', 0, 'totalSpent', 0, 'daysElapsed', 0, 'daysRemaining', 0\n    );\n  end if;\n\n  v_days_elapsed := ceil(extract(epoch from (now() - v_first_start)) / 86400);\n  v_days_remaining := ceil(extract(epoch from (v_first_end - v_first_start)) / 86400) - v_days_elapsed;\n  v_overall_burn_rate := case when v_total_budgeted > 0 then (v_total_spent / v_total_budgeted) * 100 else 0 end;\n\n  return jsonb_build_object(\n    'budgets', v_budgets,\n    'overallBurnRate', round(v_overall_burn_rate, 2),\n    'totalBudgeted', v_total_budgeted,\n    'totalSpent', v_total_spent,\n    'totalRemaining', v_total_budgeted - v_total_spent,\n    'daysElapsed', v_days_elapsed,\n    'daysRemaining', v_days_remaining,\n    'message', case when v_overall_burn_rate > 100\n      then format('⚠️ You are %s%% through your budgets. Slow down!', round(v_overall_burn_rate, 0))\n      else format('✓ You are %s%% through your budgets. On track!', round(v_overall_burn_rate, 0)) end\n  );\nend;\n$$",
 "grant execute on function public.budgets_performance() to authenticated",
 "create or replace function public.budgets_suggestions()\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_suggestions jsonb;\nbegin\n  with budgeted as (\n    select distinct category_id from public.budgets\n    where owner_id = auth.uid() and category_id is not null\n  ),\n  spending as (\n    select t.category_id, c.name, c.icon, c.color,\n           sum(t.amount) as total, count(*) as cnt\n    from public.transactions t\n    join public.categories c on c.id = t.category_id\n    where t.owner_id = auth.uid()\n      and t.type = 'expense' and t.status = 'completed'\n      and t.date >= now() - interval '30 days' and t.date <= now()\n      and t.category_id is not null\n      and t.category_id not in (select category_id from budgeted)\n    group by t.category_id, c.name, c.icon, c.color\n    order by total desc\n    limit 5\n  )\n  select coalesce(jsonb_agg(jsonb_build_object(\n    'categoryId', category_id, 'categoryName', name, 'categoryIcon', icon, 'categoryColor', color,\n    'averageMonthlySpend', round(total / 30, 2),\n    'totalSpentIn30Days', total, 'transactionCount', cnt,\n    'suggestedBudget', ceil(total / 30 * 1.2)\n  )), '[]'::jsonb)\n  into v_suggestions\n  from spending;\n\n  return jsonb_build_object(\n    'suggestions', v_suggestions,\n    'message', case when jsonb_array_length(v_suggestions) > 0\n      then format('We found %s categories you spend on frequently. Create budgets to track them better!', jsonb_array_length(v_suggestions))\n      else 'No unbudgeted spending found in the last 30 days.' end,\n    'period', jsonb_build_object('startDate', now() - interval '30 days', 'endDate', now(), 'days', 30)\n  );\nend;\n$$",
 "grant execute on function public.budgets_suggestions() to authenticated",
 "create or replace function public.budgets_summary()\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_total integer;\n  v_active integer;\n  v_exceeded integer;\n  v_total_budgeted numeric := 0;\n  v_total_spent numeric := 0;\n  v_current_count integer;\n  r record;\nbegin\n  select count(*) into v_total from public.budgets where owner_id = auth.uid();\n  select count(*) into v_active from public.budgets where owner_id = auth.uid() and status = 'active';\n  select count(*) into v_exceeded from public.budgets where owner_id = auth.uid() and status = 'exceeded';\n\n  v_current_count := 0;\n  for r in\n    select * from public.budgets\n    where owner_id = auth.uid() and status in ('active', 'exceeded')\n      and start_date <= now() and end_date >= now()\n  loop\n    v_current_count := v_current_count + 1;\n    v_total_budgeted := v_total_budgeted + r.amount;\n    v_total_spent := v_total_spent + public.budget_calculate_spent(r.owner_id, r.category_id, r.start_date, r.end_date);\n  end loop;\n\n  return jsonb_build_object(\n    'totalBudgets', v_total, 'activeBudgets', v_active, 'exceededBudgets', v_exceeded,\n    'currentBudgetsCount', v_current_count,\n    'totalBudgeted', v_total_budgeted, 'totalSpent', v_total_spent,\n    'totalRemaining', v_total_budgeted - v_total_spent\n  );\nend;\n$$",
 "grant execute on function public.budgets_summary() to authenticated",
 "create or replace function public.obligations_create(\n  p_direction obligation_direction,\n  p_name text,\n  p_counterparty text,\n  p_principal_amount numeric,\n  p_start_date timestamptz,\n  p_counterparty_contact text default null,\n  p_currency text default 'PHP',\n  p_interest_rate numeric default null,\n  p_interest_type interest_type default null,\n  p_due_date timestamptz default null,\n  p_wallet_id uuid default null,\n  p_category_id uuid default null,\n  p_notes text default null,\n  p_tags text[] default '{}',\n  p_is_installment boolean default false,\n  p_installment_amount numeric default null,\n  p_total_installments integer default null,\n  p_installment_frequency installment_frequency default null\n)\nreturns public.obligations\nlanguage plpgsql\nas $$\ndeclare\n  v_total_with_interest numeric;\n  v_obligation public.obligations;\n  v_wallet public.wallets;\n  v_disbursement_tx public.transactions;\n  v_due_dates timestamptz[];\n  v_due_date timestamptz;\n  v_bill public.bills;\n  v_txn public.transactions;\nbegin\n  if p_is_installment and (p_installment_amount is null or p_total_installments is null or p_installment_frequency is null) then\n    raise exception 'installmentAmount, totalInstallments, and installmentFrequency are required for installment obligations.'\n      using errcode = 'P0001';\n  end if;\n\n  v_total_with_interest := case when p_interest_rate is not null and p_interest_type is not null\n    then public.compute_total_with_interest(p_principal_amount, p_interest_rate, p_interest_type, p_start_date, p_due_date)\n    else null end;\n\n  insert into public.obligations (\n    owner_id, direction, name, counterparty, counterparty_contact, principal_amount,\n    remaining_balance, currency, interest_rate, interest_type, total_with_interest,\n    start_date, due_date, wallet_id, category_id, notes, tags, status,\n    is_installment, installment_amount, total_installments, paid_installments, installment_frequency\n  ) values (\n    auth.uid(), p_direction, p_name, p_counterparty, p_counterparty_contact, p_principal_amount,\n    coalesce(v_total_with_interest, p_principal_amount), coalesce(p_currency, 'PHP'),\n    p_interest_rate, p_interest_type, v_total_with_interest,\n    p_start_date, p_due_date, p_wallet_id, p_category_id, p_notes, coalesce(p_tags, '{}'), 'active',\n    coalesce(p_is_installment, false), p_installment_amount, p_total_installments, 0, p_installment_frequency\n  )\n  returning * into v_obligation;\n\n  if p_wallet_id is not null then\n    update public.wallets\n    set balance = balance + case when p_direction = 'debt' then p_principal_amount else -p_principal_amount end\n    where id = p_wallet_id and owner_id = auth.uid()\n    returning * into v_wallet;\n\n    if not found then\n      raise exception 'Wallet not found.' using errcode = 'P0002';\n    end if;\n\n    if v_wallet.balance < 0 and p_direction <> 'debt' then\n      raise exception 'Insufficient wallet balance to lend this amount.' using errcode = 'P0001';\n    end if;\n\n    insert into public.transactions (\n      owner_id, wallet_id, category_id, amount, type, description, date, attachments, tags, status\n    ) values (\n      auth.uid(), p_wallet_id, p_category_id, p_principal_amount,\n      case when p_direction = 'debt' then 'income' else 'expense' end,\n      format('%s %s: %s', case when p_direction = 'debt' then 'Borrowed from' else 'Lent to' end, p_counterparty, p_name),\n      p_start_date, '{}', coalesce(p_tags, '{}'), 'completed'\n    )\n    returning * into v_disbursement_tx;\n\n    update public.obligations set disbursement_transaction_id = v_disbursement_tx.id where id = v_obligation.id;\n  end if;\n\n  if p_is_installment and p_installment_frequency is not null and p_installment_amount is not null and p_total_installments is not null then\n    v_due_dates := public.build_installment_dates(p_start_date, p_installment_frequency, p_total_installments);\n\n    foreach v_due_date in array v_due_dates loop\n      insert into public.bills (\n        owner_id, name, amount, category_id, due_date, is_recurring, type,\n        wallet_id, reminder, reminder_days, payment_status, status, obligation_id\n      ) values (\n        auth.uid(), p_name || ' — Installment', p_installment_amount, p_category_id, v_due_date, false,\n        case when p_direction = 'debt' then 'bill' else 'income' end,\n        p_wallet_id, true, 3, 'unpaid', 'active', v_obligation.id\n      )\n      returning * into v_bill;\n\n      if p_wallet_id is not null then\n        insert into public.transactions (\n          owner_id, wallet_id, category_id, amount, type, description, date,\n          attachments, tags, bill_id, status\n        ) values (\n          auth.uid(), p_wallet_id, p_category_id, p_installment_amount,\n          case when p_direction = 'debt' then 'expense' else 'income' end,\n          p_name || ' — Installment', v_due_date, '{}', coalesce(p_tags, '{}'), v_bill.id, 'pending'\n        )\n        returning * into v_txn;\n\n        update public.bills set transaction_id = v_txn.id where id = v_bill.id;\n      end if;\n    end loop;\n  end if;\n\n  select * into v_obligation from public.obligations where id = v_obligation.id;\n  return v_obligation;\nend;\n$$",
 "grant execute on function public.obligations_create(\n  obligation_direction, text, text, numeric, timestamptz, text, text, numeric, interest_type,\n  timestamptz, uuid, uuid, text, text[], boolean, numeric, integer, installment_frequency\n) to authenticated",
 "create or replace function public.obligations_record_payment(\n  p_id uuid,\n  p_amount numeric,\n  p_wallet_id uuid,\n  p_date timestamptz default null,\n  p_notes text default null,\n  p_idempotency_key text default null\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_obligation public.obligations;\n  v_wallet public.wallets;\n  v_payment_date timestamptz;\n  v_transaction_type transaction_type;\n  v_balance_delta numeric;\n  v_new_remaining numeric;\n  v_new_status obligation_status;\n  v_unpaid_bill public.bills;\nbegin\n  if p_idempotency_key is not null and exists (\n    select 1 from public.transactions\n    where owner_id = auth.uid() and idempotency_key = p_idempotency_key\n      and created_at >= now() - interval '24 hours' and status = 'completed'\n  ) then\n    return jsonb_build_object('id', p_id, 'message', 'Payment already recorded (cached).');\n  end if;\n\n  select * into v_obligation from public.obligations where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Obligation not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  if v_obligation.status in ('settled', 'archived') then\n    raise exception 'Cannot record payment on a % obligation.', v_obligation.status using errcode = 'P0001';\n  end if;\n\n  v_transaction_type := case when v_obligation.direction = 'debt' then 'expense' else 'income' end;\n  v_balance_delta := case when v_obligation.direction = 'debt' then -p_amount else p_amount end;\n\n  update public.wallets set balance = balance + v_balance_delta\n  where id = p_wallet_id and owner_id = auth.uid()\n  returning * into v_wallet;\n\n  if not found then\n    raise exception 'Wallet not found.' using errcode = 'P0002';\n  end if;\n\n  if v_wallet.balance < 0 and v_obligation.direction = 'debt' then\n    raise exception 'Insufficient wallet balance.' using errcode = 'P0001';\n  end if;\n\n  v_payment_date := coalesce(p_date, now());\n\n  insert into public.transactions (\n    owner_id, wallet_id, amount, type, description, date, attachments, tags, status, idempotency_key\n  ) values (\n    auth.uid(), p_wallet_id, p_amount, v_transaction_type,\n    coalesce(p_notes, format('%s %s: %s',\n      case when v_obligation.direction = 'debt' then 'Repayment to' else 'Received from' end,\n      v_obligation.counterparty, v_obligation.name)),\n    v_payment_date, '{}', '{}', 'completed', p_idempotency_key\n  );\n\n  v_new_remaining := round(greatest(0, v_obligation.remaining_balance - p_amount)::numeric, 2);\n  v_new_status := case\n    when v_new_remaining <= 0 then 'settled'\n    when v_obligation.paid_installments > 0 or v_new_remaining < v_obligation.remaining_balance then 'partially_paid'\n    else 'active'\n  end;\n\n  update public.obligations set remaining_balance = v_new_remaining, status = v_new_status where id = p_id;\n\n  if v_obligation.is_installment then\n    select * into v_unpaid_bill from public.bills\n    where obligation_id = v_obligation.id and payment_status = 'unpaid' and status = 'active'\n    order by due_date asc limit 1;\n\n    if found then\n      update public.bills\n      set payment_status = case when p_amount >= v_unpaid_bill.amount then 'paid' else 'partial' end,\n          paid_amount = p_amount, last_paid_date = v_payment_date\n      where id = v_unpaid_bill.id;\n\n      if v_unpaid_bill.transaction_id is not null then\n        update public.transactions\n        set status = 'completed', amount = p_amount, date = v_payment_date\n        where id = v_unpaid_bill.transaction_id;\n      end if;\n\n      update public.obligations set paid_installments = paid_installments + 1 where id = v_obligation.id;\n    end if;\n  end if;\n\n  return jsonb_build_object('remainingBalance', v_new_remaining, 'status', v_new_status);\nend;\n$$",
 "grant execute on function public.obligations_record_payment(uuid, numeric, uuid, timestamptz, text, text) to authenticated",
 "create or replace function public.obligations_summary()\nreturns jsonb\nlanguage plpgsql\nstable\nas $$\ndeclare\n  v_debt jsonb;\n  v_lending jsonb;\nbegin\n  select jsonb_build_object(\n    'totalPrincipal', coalesce(sum(principal_amount), 0),\n    'totalRemaining', coalesce(sum(remaining_balance), 0),\n    'count', count(*),\n    'activeCount', count(*) filter (where status in ('active', 'partially_paid'))\n  ) into v_debt\n  from public.obligations where owner_id = auth.uid() and direction = 'debt' and status <> 'archived';\n\n  select jsonb_build_object(\n    'totalPrincipal', coalesce(sum(principal_amount), 0),\n    'totalRemaining', coalesce(sum(remaining_balance), 0),\n    'count', count(*),\n    'activeCount', count(*) filter (where status in ('active', 'partially_paid'))\n  ) into v_lending\n  from public.obligations where owner_id = auth.uid() and direction = 'lending' and status <> 'archived';\n\n  return jsonb_build_object(\n    'debt', v_debt, 'lending', v_lending,\n    'netPosition', round(((v_lending->>'totalRemaining')::numeric - (v_debt->>'totalRemaining')::numeric)::numeric, 2)\n  );\nend;\n$$",
 "grant execute on function public.obligations_summary() to authenticated",
 "create or replace function public.investments_create(\n  p_name text,\n  p_type investment_type,\n  p_principal_amount numeric,\n  p_start_date timestamptz,\n  p_currency text default 'PHP',\n  p_platform text default null,\n  p_wallet_id uuid default null,\n  p_category_id uuid default null,\n  p_maturity_date timestamptz default null,\n  p_expected_return_rate numeric default null,\n  p_notes text default null,\n  p_tags text[] default '{}'\n)\nreturns public.investments\nlanguage plpgsql\nas $$\ndeclare\n  v_investment public.investments;\n  v_wallet public.wallets;\n  v_funding_tx public.transactions;\nbegin\n  insert into public.investments (\n    owner_id, name, type, principal_amount, current_value, currency, platform,\n    wallet_id, category_id, start_date, maturity_date, expected_return_rate,\n    dividends_received, notes, tags, status\n  ) values (\n    auth.uid(), p_name, p_type, p_principal_amount, p_principal_amount, coalesce(p_currency, 'PHP'), p_platform,\n    p_wallet_id, p_category_id, p_start_date, p_maturity_date, p_expected_return_rate,\n    0, p_notes, coalesce(p_tags, '{}'), 'active'\n  )\n  returning * into v_investment;\n\n  insert into public.investment_value_snapshots (investment_id, value, snapshot_date)\n  values (v_investment.id, p_principal_amount, p_start_date);\n\n  if p_wallet_id is not null then\n    update public.wallets set balance = balance - p_principal_amount\n    where id = p_wallet_id and owner_id = auth.uid()\n    returning * into v_wallet;\n\n    if not found then\n      raise exception 'Wallet not found.' using errcode = 'P0002';\n    end if;\n\n    if v_wallet.balance < 0 then\n      raise exception 'Insufficient wallet balance to fund this investment.' using errcode = 'P0001';\n    end if;\n\n    insert into public.transactions (\n      owner_id, wallet_id, category_id, amount, type, description, date, attachments, tags, status\n    ) values (\n      auth.uid(), p_wallet_id, p_category_id, p_principal_amount, 'expense',\n      format('Investment: %s (%s)', p_name, p_type), p_start_date, '{}', coalesce(p_tags, '{}'), 'completed'\n    )\n    returning * into v_funding_tx;\n\n    update public.investments set funding_transaction_id = v_funding_tx.id where id = v_investment.id;\n  end if;\n\n  select * into v_investment from public.investments where id = v_investment.id;\n  return v_investment;\nend;\n$$",
 "grant execute on function public.investments_create(\n  text, investment_type, numeric, timestamptz, text, text, uuid, uuid, timestamptz, numeric, text, text[]\n) to authenticated",
 "create or replace function public.investments_update_value(\n  p_id uuid,\n  p_value numeric,\n  p_date timestamptz default null,\n  p_notes text default null\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_snapshot_date timestamptz := coalesce(p_date, now());\nbegin\n  update public.investments set current_value = p_value\n  where id = p_id and owner_id = auth.uid();\n\n  if not found then\n    raise exception 'Investment not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  insert into public.investment_value_snapshots (investment_id, value, snapshot_date, notes)\n  values (p_id, p_value, v_snapshot_date, p_notes);\n\n  return jsonb_build_object('currentValue', p_value, 'snapshot', jsonb_build_object(\n    'value', p_value, 'date', v_snapshot_date, 'notes', p_notes\n  ));\nend;\n$$",
 "grant execute on function public.investments_update_value(uuid, numeric, timestamptz, text) to authenticated",
 "create or replace function public.investments_record_return(\n  p_id uuid,\n  p_amount numeric,\n  p_wallet_id uuid,\n  p_date timestamptz default null,\n  p_notes text default null\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_investment public.investments;\n  v_return_date timestamptz := coalesce(p_date, now());\n  v_new_dividends numeric;\nbegin\n  select * into v_investment from public.investments where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Investment not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  update public.wallets set balance = balance + p_amount\n  where id = p_wallet_id and owner_id = auth.uid();\n\n  insert into public.transactions (\n    owner_id, wallet_id, category_id, amount, type, description, date, attachments, tags, status\n  ) values (\n    auth.uid(), p_wallet_id, v_investment.category_id, p_amount, 'income',\n    coalesce(p_notes, format('Investment return: %s', v_investment.name)),\n    v_return_date, '{}', v_investment.tags, 'completed'\n  );\n\n  update public.investments set dividends_received = dividends_received + p_amount\n  where id = p_id\n  returning dividends_received into v_new_dividends;\n\n  return jsonb_build_object('amount', p_amount, 'dividendsReceived', v_new_dividends);\nend;\n$$",
 "grant execute on function public.investments_record_return(uuid, numeric, uuid, timestamptz, text) to authenticated",
 "create or replace function public.investments_sell(\n  p_id uuid,\n  p_sale_amount numeric,\n  p_wallet_id uuid,\n  p_date timestamptz default null,\n  p_notes text default null\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_investment public.investments;\n  v_sale_date timestamptz := coalesce(p_date, now());\n  v_gain_loss numeric;\nbegin\n  select * into v_investment from public.investments where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Investment not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  if v_investment.status in ('sold', 'archived') then\n    raise exception 'Cannot sell a % investment.', v_investment.status using errcode = 'P0001';\n  end if;\n\n  v_gain_loss := round((p_sale_amount - v_investment.principal_amount)::numeric, 2);\n\n  update public.wallets set balance = balance + p_sale_amount\n  where id = p_wallet_id and owner_id = auth.uid();\n\n  insert into public.transactions (\n    owner_id, wallet_id, category_id, amount, type, description, date, attachments, tags, status\n  ) values (\n    auth.uid(), p_wallet_id, v_investment.category_id, p_sale_amount, 'income',\n    coalesce(p_notes, format('Sale of investment: %s', v_investment.name)),\n    v_sale_date, '{}', v_investment.tags, 'completed'\n  );\n\n  update public.investments set status = 'sold', current_value = p_sale_amount where id = p_id;\n\n  insert into public.investment_value_snapshots (investment_id, value, snapshot_date, notes)\n  values (p_id, p_sale_amount, v_sale_date, coalesce(p_notes, 'Sold'));\n\n  return jsonb_build_object('saleAmount', p_sale_amount, 'gainLoss', v_gain_loss);\nend;\n$$",
 "grant execute on function public.investments_sell(uuid, numeric, uuid, timestamptz, text) to authenticated",
 "create or replace function public.investments_summary()\nreturns jsonb\nlanguage plpgsql\nstable\nas $$\ndeclare\n  v_total_invested numeric;\n  v_total_current numeric;\n  v_total_dividends numeric;\n  v_count integer;\n  v_active_count integer;\n  v_total_gain_loss numeric;\n  v_return_rate numeric;\n  v_by_type jsonb;\nbegin\n  select\n    coalesce(sum(principal_amount), 0), coalesce(sum(current_value), 0), coalesce(sum(dividends_received), 0),\n    count(*), count(*) filter (where status = 'active')\n  into v_total_invested, v_total_current, v_total_dividends, v_count, v_active_count\n  from public.investments where owner_id = auth.uid() and status <> 'archived';\n\n  v_total_gain_loss := round((v_total_current - v_total_invested + v_total_dividends)::numeric, 2);\n  v_return_rate := case when v_total_invested > 0 then round((v_total_gain_loss / v_total_invested) * 100, 2) else 0 end;\n\n  select coalesce(jsonb_agg(jsonb_build_object(\n    'type', type, 'totalInvested', total_invested, 'totalCurrentValue', total_current,\n    'count', cnt, 'gainLoss', round((total_current - total_invested)::numeric, 2)\n  )), '[]'::jsonb)\n  into v_by_type\n  from (\n    select type, sum(principal_amount) as total_invested, sum(current_value) as total_current, count(*) as cnt\n    from public.investments where owner_id = auth.uid() and status <> 'archived'\n    group by type\n  ) t;\n\n  return jsonb_build_object(\n    'totalInvested', v_total_invested, 'totalCurrentValue', v_total_current, 'totalDividends', v_total_dividends,\n    'totalGainLoss', v_total_gain_loss, 'returnRate', v_return_rate,\n    'count', v_count, 'activeCount', v_active_count, 'byType', v_by_type\n  );\nend;\n$$",
 "grant execute on function public.investments_summary() to authenticated",
 "create or replace function public.reports_monthly(\n  p_month integer default null,\n  p_year integer default null,\n  p_wallet_id uuid default null\n)\nreturns jsonb\nlanguage plpgsql\nstable\nas $$\ndeclare\n  v_month integer := coalesce(p_month, extract(month from now())::integer);\n  v_year integer := coalesce(p_year, extract(year from now())::integer);\n  v_start timestamptz := make_timestamptz(v_year, v_month, 1, 0, 0, 0);\n  v_end timestamptz := (v_start + interval '1 month') - interval '1 second';\n  v_income numeric := 0; v_income_count integer := 0;\n  v_expense numeric := 0; v_expense_count integer := 0;\n  v_transfer numeric := 0; v_transfer_count integer := 0;\nbegin\n  select\n    coalesce(sum(amount) filter (where type = 'income'), 0),\n    count(*) filter (where type = 'income'),\n    coalesce(sum(amount) filter (where type = 'expense'), 0),\n    count(*) filter (where type = 'expense'),\n    coalesce(sum(amount) filter (where type = 'transfer'), 0),\n    count(*) filter (where type = 'transfer')\n  into v_income, v_income_count, v_expense, v_expense_count, v_transfer, v_transfer_count\n  from public.transactions\n  where owner_id = auth.uid() and status = 'completed'\n    and date >= v_start and date <= v_end\n    and (p_wallet_id is null or wallet_id = p_wallet_id);\n\n  return jsonb_build_object(\n    'month', v_month, 'year', v_year,\n    'income', v_income, 'incomeCount', v_income_count,\n    'expense', v_expense, 'expenseCount', v_expense_count,\n    'transfers', v_transfer, 'transferCount', v_transfer_count,\n    'netCashFlow', v_income - v_expense\n  );\nend;\n$$",
 "grant execute on function public.reports_monthly(integer, integer, uuid) to authenticated",
 "create or replace function public.reports_category_breakdown(\n  p_type transaction_type,\n  p_period text default null,\n  p_start timestamptz default null,\n  p_end timestamptz default null,\n  p_wallet_id uuid default null\n)\nreturns jsonb\nlanguage plpgsql\nstable\nas $$\ndeclare\n  v_start timestamptz;\n  v_end timestamptz := now();\n  v_breakdown jsonb;\n  v_total numeric;\n  v_transaction_count integer;\nbegin\n  if p_period = 'today' then v_start := date_trunc('day', now());\n  elsif p_period = 'week' then v_start := date_trunc('week', now());\n  elsif p_period = 'month' then v_start := date_trunc('month', now());\n  elsif p_period = 'year' then v_start := date_trunc('year', now());\n  elsif p_period = 'all' then v_start := make_timestamptz(2000, 1, 1, 0, 0, 0);\n  else v_start := p_start; v_end := coalesce(p_end, now());\n  end if;\n\n  with breakdown as (\n    select t.category_id, c.name, c.icon, c.color,\n           sum(t.amount) as total, count(*) as cnt\n    from public.transactions t\n    left join public.categories c on c.id = t.category_id\n    where t.owner_id = auth.uid() and t.type = p_type and t.status = 'completed'\n      and (v_start is null or t.date >= v_start) and t.date <= v_end\n      and (p_wallet_id is null or t.wallet_id = p_wallet_id)\n    group by t.category_id, c.name, c.icon, c.color\n  )\n  select coalesce(sum(total), 0), coalesce(sum(cnt), 0) into v_total, v_transaction_count from breakdown;\n\n  with breakdown as (\n    select t.category_id, c.name, c.icon, c.color,\n           sum(t.amount) as total, count(*) as cnt\n    from public.transactions t\n    left join public.categories c on c.id = t.category_id\n    where t.owner_id = auth.uid() and t.type = p_type and t.status = 'completed'\n      and (v_start is null or t.date >= v_start) and t.date <= v_end\n      and (p_wallet_id is null or t.wallet_id = p_wallet_id)\n    group by t.category_id, c.name, c.icon, c.color\n    order by sum(t.amount) desc\n  )\n  select coalesce(jsonb_agg(jsonb_build_object(\n    'categoryId', category_id, 'categoryName', coalesce(name, 'Uncategorized'),\n    'categoryIcon', icon, 'categoryColor', color, 'total', total, 'count', cnt,\n    'percentage', case when v_total > 0 then round((total / v_total) * 100, 2) else 0 end\n  )), '[]'::jsonb)\n  into v_breakdown\n  from breakdown;\n\n  return jsonb_build_object(\n    'breakdown', v_breakdown, 'totalAmount', v_total,\n    'transactionCount', v_transaction_count\n  );\nend;\n$$",
 "grant execute on function public.reports_category_breakdown(transaction_type, text, timestamptz, timestamptz, uuid) to authenticated",
 "create or replace function public.reports_dashboard_summary(\n  p_month integer default null,\n  p_year integer default null,\n  p_wallet_id uuid default null\n)\nreturns jsonb\nlanguage plpgsql\nstable\nas $$\ndeclare\n  v_month integer := coalesce(p_month, extract(month from now())::integer);\n  v_year integer := coalesce(p_year, extract(year from now())::integer);\n  v_income numeric := 0; v_income_count integer := 0;\n  v_expense numeric := 0; v_expense_count integer := 0;\n  v_transfer numeric := 0; v_transfer_count integer := 0;\nbegin\n  if v_month < 1 or v_month > 12 then\n    raise exception 'Invalid month. Please provide a month between 1 and 12.' using errcode = 'P0001';\n  end if;\n\n  select\n    coalesce(sum(amount) filter (where type = 'income'), 0),\n    count(*) filter (where type = 'income'),\n    coalesce(sum(amount) filter (where type = 'expense'), 0),\n    count(*) filter (where type = 'expense'),\n    coalesce(sum(amount) filter (where type = 'transfer'), 0),\n    count(*) filter (where type = 'transfer')\n  into v_income, v_income_count, v_expense, v_expense_count, v_transfer, v_transfer_count\n  from public.transactions\n  where owner_id = auth.uid() and status = 'completed'\n    and (p_wallet_id is null or wallet_id = p_wallet_id);\n\n  return jsonb_build_object(\n    'totalIncome', round(v_income, 2), 'incomeCount', v_income_count,\n    'totalExpenses', round(v_expense, 2), 'expenseCount', v_expense_count,\n    'totalTransfers', round(v_transfer, 2), 'transferCount', v_transfer_count,\n    'totalTransactions', v_income_count + v_expense_count + v_transfer_count,\n    'netCashFlow', round(v_income - v_expense, 2),\n    'month', v_month, 'year', v_year\n  );\nend;\n$$",
 "grant execute on function public.reports_dashboard_summary(integer, integer, uuid) to authenticated",
 "create or replace function public.reports_quick_stats(\n  p_period text default 'month',\n  p_wallet_id uuid default null\n)\nreturns jsonb\nlanguage plpgsql\nstable\nas $$\ndeclare\n  v_start timestamptz;\n  v_end timestamptz := now();\n  v_income numeric := 0; v_expense numeric := 0; v_transfer numeric := 0; v_count integer := 0;\nbegin\n  if p_period = 'today' then v_start := date_trunc('day', now());\n  elsif p_period = 'week' then v_start := date_trunc('week', now());\n  elsif p_period = 'year' then v_start := date_trunc('year', now());\n  elsif p_period = 'all' then v_start := make_timestamptz(2000, 1, 1, 0, 0, 0);\n  else v_start := date_trunc('month', now());\n  end if;\n\n  select\n    coalesce(sum(amount) filter (where type = 'income'), 0),\n    coalesce(sum(amount) filter (where type = 'expense'), 0),\n    coalesce(sum(amount) filter (where type = 'transfer'), 0),\n    count(*)\n  into v_income, v_expense, v_transfer, v_count\n  from public.transactions\n  where owner_id = auth.uid() and status = 'completed'\n    and date >= v_start and date <= v_end\n    and (p_wallet_id is null or wallet_id = p_wallet_id);\n\n  return jsonb_build_object(\n    'period', p_period, 'income', round(v_income, 2), 'expenses', round(v_expense, 2),\n    'transfers', round(v_transfer, 2), 'transactions', v_count,\n    'startDate', v_start, 'endDate', v_end\n  );\nend;\n$$",
 "grant execute on function public.reports_quick_stats(text, uuid) to authenticated",
 "create or replace function public.reports_analytics(\n  p_period text,\n  p_wallet_id uuid default null\n)\nreturns jsonb\nlanguage plpgsql\nstable\nas $$\ndeclare\n  v_start timestamptz;\n  v_data jsonb;\nbegin\n  if p_period = 'daily' then v_start := now() - interval '30 days';\n  elsif p_period = 'weekly' then v_start := now() - interval '364 days';\n  else v_start := now() - interval '5 years';\n  end if;\n\n  if p_period = 'daily' then\n    with buckets as (\n      select date_trunc('day', date) as bucket,\n             sum(amount) filter (where type = 'income') as income,\n             sum(amount) filter (where type = 'expense') as expenses,\n             count(*) as cnt\n      from public.transactions\n      where owner_id = auth.uid() and status = 'completed' and type in ('income', 'expense')\n        and date >= v_start and date <= now()\n        and (p_wallet_id is null or wallet_id = p_wallet_id)\n      group by 1\n    )\n    select coalesce(jsonb_agg(jsonb_build_object(\n      'date', to_char(bucket, 'YYYY-MM-DD'),\n      'income', round(coalesce(income, 0), 2), 'expenses', round(coalesce(expenses, 0), 2),\n      'net', round(coalesce(income, 0) - coalesce(expenses, 0), 2), 'transactionCount', cnt\n    ) order by bucket desc), '[]'::jsonb) into v_data from buckets;\n  elsif p_period = 'weekly' then\n    with buckets as (\n      select date_trunc('week', date) as bucket,\n             extract(week from date) as wk, extract(month from date) as mo, extract(year from date) as yr,\n             sum(amount) filter (where type = 'income') as income,\n             sum(amount) filter (where type = 'expense') as expenses,\n             count(*) as cnt\n      from public.transactions\n      where owner_id = auth.uid() and status = 'completed' and type in ('income', 'expense')\n        and date >= v_start and date <= now()\n        and (p_wallet_id is null or wallet_id = p_wallet_id)\n      group by 1, 3, 4\n    )\n    select coalesce(jsonb_agg(jsonb_build_object(\n      'week', wk, 'month', mo, 'year', yr,\n      'income', round(coalesce(income, 0), 2), 'expenses', round(coalesce(expenses, 0), 2),\n      'net', round(coalesce(income, 0) - coalesce(expenses, 0), 2), 'transactionCount', cnt\n    ) order by bucket desc), '[]'::jsonb) into v_data from buckets;\n  else\n    with buckets as (\n      select extract(year from date) as yr,\n             sum(amount) filter (where type = 'income') as income,\n             sum(amount) filter (where type = 'expense') as expenses,\n             count(*) as cnt\n      from public.transactions\n      where owner_id = auth.uid() and status = 'completed' and type in ('income', 'expense')\n        and date >= v_start and date <= now()\n        and (p_wallet_id is null or wallet_id = p_wallet_id)\n      group by 1\n    )\n    select coalesce(jsonb_agg(jsonb_build_object(\n      'year', yr, 'income', round(coalesce(income, 0), 2), 'expenses', round(coalesce(expenses, 0), 2),\n      'net', round(coalesce(income, 0) - coalesce(expenses, 0), 2), 'transactionCount', cnt\n    ) order by yr desc), '[]'::jsonb) into v_data from buckets;\n  end if;\n\n  return jsonb_build_object(\n    'period', p_period, 'walletId', p_wallet_id, 'data', v_data,\n    'summary', jsonb_build_object(\n      'totalIncome', (select coalesce(sum((x->>'income')::numeric), 0) from jsonb_array_elements(v_data) x),\n      'totalExpenses', (select coalesce(sum((x->>'expenses')::numeric), 0) from jsonb_array_elements(v_data) x),\n      'totalNet', (select coalesce(sum((x->>'net')::numeric), 0) from jsonb_array_elements(v_data) x),\n      'transactionCount', (select coalesce(sum((x->>'transactionCount')::integer), 0) from jsonb_array_elements(v_data) x)\n    )\n  );\nend;\n$$",
 "grant execute on function public.reports_analytics(text, uuid) to authenticated",
 "create or replace function public.reports_chart_data(\n  p_period text default 'month',\n  p_wallet_id uuid default null\n)\nreturns jsonb\nlanguage plpgsql\nstable\nas $$\ndeclare\n  v_start timestamptz;\n  v_end timestamptz := now();\n  v_points jsonb;\n  v_total_income numeric := 0; v_total_expenses numeric := 0; v_total_transfers numeric := 0;\nbegin\n  if p_period = 'today' then\n    v_start := date_trunc('day', now());\n    with series as (select generate_series(0, 23) as slot),\n    agg as (\n      select extract(hour from date)::int as slot,\n             sum(amount) filter (where type='income') as income,\n             sum(amount) filter (where type='expense') as expenses,\n             sum(amount) filter (where type='transfer') as transfers\n      from public.transactions\n      where owner_id = auth.uid() and status = 'completed'\n        and date >= v_start and date < v_start + interval '1 day'\n        and (p_wallet_id is null or wallet_id = p_wallet_id)\n      group by 1\n    )\n    select coalesce(jsonb_agg(jsonb_build_object(\n      'hour', s.slot, 'income', round(coalesce(a.income,0),2),\n      'expenses', round(coalesce(a.expenses,0),2), 'transfers', round(coalesce(a.transfers,0),2)\n    ) order by s.slot), '[]'::jsonb) into v_points\n    from series s left join agg a on a.slot = s.slot;\n\n  elsif p_period = 'week' then\n    v_start := date_trunc('week', now());\n    with series as (select generate_series(0, 6) as slot),\n    agg as (\n      select extract(dow from date)::int as slot,\n             sum(amount) filter (where type='income') as income,\n             sum(amount) filter (where type='expense') as expenses,\n             sum(amount) filter (where type='transfer') as transfers\n      from public.transactions\n      where owner_id = auth.uid() and status = 'completed'\n        and date >= v_start and date < v_start + interval '7 days'\n        and (p_wallet_id is null or wallet_id = p_wallet_id)\n      group by 1\n    )\n    select coalesce(jsonb_agg(jsonb_build_object(\n      'day', to_char(v_start + make_interval(days => s.slot), 'FMDay'),\n      'income', round(coalesce(a.income,0),2), 'expenses', round(coalesce(a.expenses,0),2),\n      'transfers', round(coalesce(a.transfers,0),2)\n    ) order by s.slot), '[]'::jsonb) into v_points\n    from series s left join agg a on a.slot = s.slot;\n\n  elsif p_period = 'year' then\n    v_start := date_trunc('year', now());\n    with series as (select generate_series(1, 12) as slot),\n    agg as (\n      select extract(month from date)::int as slot,\n             sum(amount) filter (where type='income') as income,\n             sum(amount) filter (where type='expense') as expenses,\n             sum(amount) filter (where type='transfer') as transfers\n      from public.transactions\n      where owner_id = auth.uid() and status = 'completed'\n        and date >= v_start and date < v_start + interval '1 year'\n        and (p_wallet_id is null or wallet_id = p_wallet_id)\n      group by 1\n    )\n    select coalesce(jsonb_agg(jsonb_build_object(\n      'month', to_char(make_date(2000, s.slot, 1), 'FMMonth'),\n      'income', round(coalesce(a.income,0),2), 'expenses', round(coalesce(a.expenses,0),2),\n      'transfers', round(coalesce(a.transfers,0),2)\n    ) order by s.slot), '[]'::jsonb) into v_points\n    from series s left join agg a on a.slot = s.slot;\n\n  elsif p_period = 'all' then\n    with agg as (\n      select extract(year from date)::int as yr,\n             sum(amount) filter (where type='income') as income,\n             sum(amount) filter (where type='expense') as expenses,\n             sum(amount) filter (where type='transfer') as transfers\n      from public.transactions\n      where owner_id = auth.uid() and status = 'completed'\n        and (p_wallet_id is null or wallet_id = p_wallet_id)\n      group by 1\n    )\n    select coalesce(jsonb_agg(jsonb_build_object(\n      'year', yr, 'income', round(coalesce(income,0),2), 'expenses', round(coalesce(expenses,0),2),\n      'transfers', round(coalesce(transfers,0),2)\n    ) order by yr), '[]'::jsonb) into v_points\n    from agg;\n    select min(make_timestamptz((x->>'year')::int, 1, 1, 0, 0, 0))\n    into v_start\n    from jsonb_array_elements(v_points) x;\n    v_start := coalesce(v_start, now());\n\n  else -- month (default)\n    v_start := date_trunc('month', now());\n    with series as (\n      select generate_series(1, extract(day from (date_trunc('month', now()) + interval '1 month - 1 day'))::int) as slot\n    ),\n    agg as (\n      select extract(day from date)::int as slot,\n             sum(amount) filter (where type='income') as income,\n             sum(amount) filter (where type='expense') as expenses,\n             sum(amount) filter (where type='transfer') as transfers\n      from public.transactions\n      where owner_id = auth.uid() and status = 'completed'\n        and date >= v_start and date < v_start + interval '1 month'\n        and (p_wallet_id is null or wallet_id = p_wallet_id)\n      group by 1\n    )\n    select coalesce(jsonb_agg(jsonb_build_object(\n      'date', to_char(v_start, 'Mon') || '.' || s.slot,\n      'income', round(coalesce(a.income,0),2), 'expenses', round(coalesce(a.expenses,0),2),\n      'transfers', round(coalesce(a.transfers,0),2)\n    ) order by s.slot), '[]'::jsonb) into v_points\n    from series s left join agg a on a.slot = s.slot;\n  end if;\n\n  select coalesce(sum((x->>'income')::numeric), 0), coalesce(sum((x->>'expenses')::numeric), 0),\n         coalesce(sum((x->>'transfers')::numeric), 0)\n  into v_total_income, v_total_expenses, v_total_transfers\n  from jsonb_array_elements(v_points) x;\n\n  return jsonb_build_object(\n    'period', p_period, 'startDate', v_start, 'endDate', v_end, 'dataPoints', v_points,\n    'totals', jsonb_build_object(\n      'income', round(v_total_income,2), 'expenses', round(v_total_expenses,2), 'transfers', round(v_total_transfers,2)\n    )\n  );\nend;\n$$",
 "grant execute on function public.reports_chart_data(text, uuid) to authenticated",
 "create or replace function public.transactions_all_tags()\nreturns jsonb\nlanguage sql\nstable\nas $$\n  select coalesce(jsonb_build_object(\n    'tags', jsonb_agg(tag order by cnt desc),\n    'tagStats', jsonb_agg(jsonb_build_object('tag', tag, 'count', cnt) order by cnt desc)\n  ), jsonb_build_object('tags', '[]'::jsonb, 'tagStats', '[]'::jsonb))\n  from (\n    select tag, count(*) as cnt\n    from public.transactions, unnest(tags) as tag\n    where owner_id = auth.uid() and status = 'completed'\n    group by tag\n    order by cnt desc\n  ) t;\n$$",
 "grant execute on function public.transactions_all_tags() to authenticated",
 "create or replace function public.transactions_spent_today(p_wallet_id uuid default null)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  select jsonb_build_object(\n    'totalSpent', round(coalesce(sum(amount), 0), 2),\n    'transactionCount', count(*),\n    'date', to_char(date_trunc('day', now()), 'YYYY-MM-DD')\n  )\n  from public.transactions\n  where owner_id = auth.uid() and type = 'expense' and status = 'completed'\n    and date >= date_trunc('day', now()) and date < date_trunc('day', now()) + interval '1 day'\n    and (p_wallet_id is null or wallet_id = p_wallet_id);\n$$",
 "grant execute on function public.transactions_spent_today(uuid) to authenticated",
 "alter table public.wallets alter column owner_id set default auth.uid()",
 "alter table public.categories alter column owner_id set default auth.uid()",
 "do $$\nbegin\n  if not exists (\n    select 1 from public.categories where owner_id is null and is_default = true\n  ) then\n    insert into public.categories (owner_id, name, type, icon, color, is_default, status)\n    values\n      (null, 'Salary', 'income', '💰', '#4CAF50', true, 'active'),\n      (null, 'Freelance', 'income', '💼', '#2196F3', true, 'active'),\n      (null, 'Business', 'income', '🏢', '#FF9800', true, 'active'),\n      (null, 'Investment', 'income', '📈', '#9C27B0', true, 'active'),\n      (null, 'Remittance', 'income', '🌐', '#00BCD4', true, 'active'),\n      (null, 'Gift', 'income', '🎁', '#E91E63', true, 'active'),\n      (null, 'Other Income', 'income', '➕', '#607D8B', true, 'active'),\n      (null, 'Food & Dining', 'expense', '🍽️', '#FF5722', true, 'active'),\n      (null, 'Groceries', 'expense', '🛒', '#8BC34A', true, 'active'),\n      (null, 'Transportation', 'expense', '🚗', '#FFC107', true, 'active'),\n      (null, 'Bills & Utilities', 'expense', '⚡', '#FF9800', true, 'active'),\n      (null, 'Rent', 'expense', '🏠', '#795548', true, 'active'),\n      (null, 'Healthcare', 'expense', '🏥', '#F44336', true, 'active'),\n      (null, 'Entertainment', 'expense', '🎬', '#9C27B0', true, 'active'),\n      (null, 'Shopping', 'expense', '🛍️', '#E91E63', true, 'active'),\n      (null, 'Education', 'expense', '📚', '#3F51B5', true, 'active'),\n      (null, 'Insurance', 'expense', '🛡️', '#00BCD4', true, 'active'),\n      (null, 'Clothing', 'expense', '👔', '#673AB7', true, 'active'),\n      (null, 'Personal Care', 'expense', '💅', '#FF4081', true, 'active'),\n      (null, 'Travel', 'expense', '✈️', '#2196F3', true, 'active'),\n      (null, 'Subscription', 'expense', '📱', '#00BCD4', true, 'active'),\n      (null, 'Donation', 'expense', '❤️', '#E91E63', true, 'active'),\n      (null, 'Other Expense', 'expense', '➖', '#607D8B', true, 'active');\n  end if;\nend $$",
 "create or replace function public.transactions_bulk_import(\n  p_wallet_id uuid,\n  p_rows jsonb\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_wallet public.wallets;\n  v_inserted integer;\nbegin\n  select * into v_wallet from public.wallets\n  where id = p_wallet_id and owner_id = auth.uid() and status = 'active';\n  if not found then\n    raise exception 'Wallet not found or inactive.' using errcode = 'P0002';\n  end if;\n\n  with rows as (\n    select *\n    from jsonb_to_recordset(p_rows) as r(\n      date timestamptz,\n      amount numeric,\n      type transaction_type,\n      description text,\n      tags text[],\n      category_id uuid\n    )\n  ),\n  inserted as (\n    insert into public.transactions (\n      owner_id, wallet_id, amount, type, description, date, tags, category_id, attachments, status\n    )\n    select auth.uid(), p_wallet_id, amount, type, description, date,\n           coalesce(tags, '{}'), category_id, '{}', 'completed'\n    from rows\n    returning 1\n  )\n  select count(*) into v_inserted from inserted;\n\n  return jsonb_build_object('imported', v_inserted);\nend;\n$$",
 "grant execute on function public.transactions_bulk_import(uuid, jsonb) to authenticated",
 "create or replace function public.wallets_set_balance(\n  p_wallet_id uuid,\n  p_balance numeric\n)\nreturns public.wallets\nlanguage plpgsql\nas $$\ndeclare\n  v_wallet public.wallets;\nbegin\n  update public.wallets\n  set balance = p_balance\n  where id = p_wallet_id\n    and owner_id = auth.uid()\n    and status = 'active'\n  returning * into v_wallet;\n\n  if not found then\n    raise exception 'Wallet not found or inactive.' using errcode = 'P0002';\n  end if;\n\n  return v_wallet;\nend;\n$$",
 "grant execute on function public.wallets_set_balance(uuid, numeric) to authenticated",
 "create or replace function public.handle_new_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  chosen text := nullif(new.raw_user_meta_data ->> 'username', '');\n  candidate text;\n  attempts integer := 0;\nbegin\n  if chosen is not null then\n    insert into public.profiles (id, username) values (new.id, chosen);\n    return new;\n  end if;\n\n  candidate := coalesce(nullif(split_part(new.email, '@', 1), ''), 'user');\n  while exists (select 1 from public.profiles where username = candidate) and attempts < 20 loop\n    attempts := attempts + 1;\n    candidate := coalesce(nullif(split_part(new.email, '@', 1), ''), 'user')\n                 || substr(md5(random()::text || new.id::text), 1, 4);\n  end loop;\n\n  insert into public.profiles (id, username) values (new.id, candidate);\n  return new;\nend;\n$$",
 "alter table public.wallets add column if not exists institution text",
 "alter table public.wallets add column if not exists credit_limit numeric(14, 2)",
 "alter type wallet_type add value if not exists 'savings'",
 "alter table public.wallets\n  add column if not exists interest_rate numeric(6, 3),            \n  add column if not exists interest_payout text,                   \n  add column if not exists interest_tax_rate numeric(5, 2),        \n  add column if not exists maturity_date date,                     \n  add column if not exists interest_last_posted_at timestamptz,\n  \n  add column if not exists total_interest_earned numeric(14, 2) not null default 0",
 "alter table public.wallets\n  add constraint wallets_interest_payout_check\n  check (interest_payout is null or interest_payout in ('monthly', 'quarterly', 'annually', 'maturity'))",
 "create or replace function public.post_savings_interest()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  w record;\n  v_months integer;\n  v_last timestamptz;\n  v_next timestamptz;\n  v_years numeric;\n  v_gross numeric;\n  v_net numeric;\n  v_posted integer := 0;\nbegin\n  for w in\n    select * from public.wallets\n    where type::text = 'savings' and status = 'active'\n      and coalesce(interest_rate, 0) > 0 and balance > 0\n      and interest_payout is not null\n  loop\n    v_last := coalesce(w.interest_last_posted_at, w.created_at);\n\n    if w.interest_payout = 'maturity' then\n      -- Single payout once the term ends; simple interest over the whole term.\n      continue when w.maturity_date is null or w.maturity_date > current_date or w.interest_last_posted_at is not null;\n      v_years := greatest((w.maturity_date - w.created_at::date)::numeric / 365, 0);\n    else\n      v_months := case w.interest_payout when 'monthly' then 1 when 'quarterly' then 3 else 12 end;\n      v_next := v_last + make_interval(months => v_months);\n      continue when v_next > now();\n      v_years := v_months::numeric / 12;\n    end if;\n\n    v_gross := round(w.balance * (w.interest_rate / 100) * v_years, 2);\n    v_net := round(v_gross * (1 - coalesce(w.interest_tax_rate, 0) / 100), 2);\n    continue when v_net <= 0;\n\n    insert into public.transactions (owner_id, wallet_id, amount, type, description, date, tags, status)\n    values (w.owner_id, w.id, v_net, 'income', 'Interest earned', now(), array['interest'], 'completed');\n\n    update public.wallets\n    set balance = balance + v_net,\n        total_interest_earned = total_interest_earned + v_net,\n        interest_last_posted_at = case when w.interest_payout = 'maturity' then now() else v_next end\n    where id = w.id;\n\n    v_posted := v_posted + 1;\n  end loop;\n\n  return v_posted;\nend;\n$$",
 "alter table public.profiles add column if not exists avatar_url text",
 "alter table public.wallets\n  add column if not exists statement_day smallint check (statement_day between 1 and 28),\n  add column if not exists due_day smallint check (due_day between 1 and 28)",
 "alter table public.bills\n  add column if not exists pays_wallet_id uuid references public.wallets(id)",
 "create or replace function public.wallet_apply(p_wallet_id uuid, p_delta numeric)\nreturns public.wallets\nlanguage plpgsql\nas $$\ndeclare\n  v_wallet public.wallets;\nbegin\n  update public.wallets\n  set balance = balance + case when type::text = 'credit_card' then -p_delta else p_delta end\n  where id = p_wallet_id and owner_id = auth.uid()\n  returning * into v_wallet;\n  return v_wallet;\nend;\n$$",
 "create or replace function public.wallet_can_afford(p_wallet public.wallets, p_amount numeric)\nreturns boolean\nlanguage sql\nimmutable\nas $$\n  select case\n    when p_wallet.type::text = 'credit_card' then p_wallet.credit_limit is null or p_wallet.balance + p_amount <= p_wallet.credit_limit\n    else p_wallet.balance >= p_amount\n  end;\n$$",
 "create or replace function public.transactions_create(\n  p_wallet_id uuid,\n  p_amount numeric,\n  p_type transaction_type,\n  p_category_id uuid default null,\n  p_description text default null,\n  p_date timestamptz default now(),\n  p_attachments text[] default '{}',\n  p_tags text[] default '{}',\n  p_to_wallet_id uuid default null,\n  p_bill_id uuid default null,\n  p_service_fee numeric default 0,\n  p_create_bill_for_fee boolean default false\n)\nreturns public.transactions\nlanguage plpgsql\nas $$\ndeclare\n  v_wallet public.wallets;\n  v_to_wallet public.wallets;\n  v_immediate_fee numeric := 0;\n  v_total_deduction numeric;\n  v_fee_deducted boolean := false;\n  v_txn public.transactions;\n  v_fee_due_date timestamptz;\n  v_fee_txn public.transactions;\nbegin\n  select * into v_wallet from public.wallets\n  where id = p_wallet_id and owner_id = auth.uid() and status = 'active';\n  if not found then\n    raise exception 'Wallet not found or inactive.' using errcode = 'P0002';\n  end if;\n\n  if p_type = 'transfer' then\n    if p_to_wallet_id is null then\n      raise exception 'Destination wallet required for transfers.' using errcode = 'P0001';\n    end if;\n    if p_wallet_id = p_to_wallet_id then\n      raise exception 'Cannot transfer to the same wallet.' using errcode = 'P0001';\n    end if;\n    select * into v_to_wallet from public.wallets\n    where id = p_to_wallet_id and owner_id = auth.uid() and status = 'active';\n    if not found then\n      raise exception 'Destination wallet not found or inactive.' using errcode = 'P0002';\n    end if;\n  end if;\n\n  v_immediate_fee := case when not p_create_bill_for_fee and p_service_fee > 0 then p_service_fee else 0 end;\n  v_total_deduction := case when p_type = 'transfer' then p_amount + v_immediate_fee else p_amount end;\n\n  if p_type in ('expense', 'transfer') and not public.wallet_can_afford(v_wallet, v_total_deduction) then\n    if v_wallet.type::text = 'credit_card' then\n      raise exception 'This would go over the card''s credit limit.' using errcode = 'P0001';\n    end if;\n    raise exception 'Insufficient wallet balance for transaction%',\n      case when v_immediate_fee > 0 then ' and service fee.' else '.' end\n      using errcode = 'P0001';\n  end if;\n\n  v_fee_deducted := (p_type = 'transfer' and p_service_fee > 0 and not p_create_bill_for_fee);\n\n  insert into public.transactions (\n    owner_id, wallet_id, category_id, amount, type, description, date,\n    attachments, tags, to_wallet_id, bill_id, service_fee, service_fee_deducted, status\n  ) values (\n    auth.uid(), p_wallet_id, p_category_id, p_amount, p_type, p_description, p_date,\n    p_attachments, p_tags, p_to_wallet_id, p_bill_id, p_service_fee, v_fee_deducted, 'completed'\n  )\n  returning * into v_txn;\n\n  if p_type = 'income' then\n    perform public.wallet_apply(p_wallet_id, p_amount);\n  elsif p_type = 'expense' then\n    perform public.wallet_apply(p_wallet_id, -p_amount);\n  elsif p_type = 'transfer' then\n    perform public.wallet_apply(p_wallet_id, -(p_amount + case when v_fee_deducted then p_service_fee else 0 end));\n    perform public.wallet_apply(p_to_wallet_id, p_amount);\n  end if;\n\n  if p_bill_id is not null then\n    update public.bills\n    set payment_status = 'paid', paid_amount = p_amount, last_paid_date = v_txn.date\n    where id = p_bill_id and owner_id = auth.uid();\n  end if;\n\n  if p_create_bill_for_fee and p_service_fee > 0 then\n    v_fee_due_date := v_txn.date + interval '1 day';\n\n    insert into public.transactions (\n      owner_id, wallet_id, amount, type, description, date, attachments, tags, status\n    ) values (\n      auth.uid(), p_wallet_id, p_service_fee, 'expense',\n      format('Service fee for transfer of %s', p_amount), v_fee_due_date, '{}', '{}', 'pending'\n    )\n    returning * into v_fee_txn;\n\n    insert into public.bills (\n      owner_id, name, amount, due_date, is_recurring, wallet_id, reminder,\n      payment_status, notes, status, transaction_id\n    ) values (\n      auth.uid(), 'Transfer Service Fee', p_service_fee, v_fee_due_date, false, p_wallet_id, false,\n      'unpaid', format('Service fee for transfer transaction ID: %s', v_txn.id), 'active', v_fee_txn.id\n    );\n  end if;\n\n  return v_txn;\nend;\n$$",
 "grant execute on function public.transactions_create(\n  uuid, numeric, transaction_type, uuid, text, timestamptz, text[], text[], uuid, uuid, numeric, boolean\n) to authenticated",
 "create or replace function public.transactions_delete(p_id uuid)\nreturns void\nlanguage plpgsql\nas $$\ndeclare\n  v_txn public.transactions;\nbegin\n  select * into v_txn from public.transactions\n  where id = p_id and owner_id = auth.uid();\n\n  if not found then\n    raise exception 'Transaction not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  if v_txn.status <> 'completed' then\n    raise exception 'Can only delete completed transactions.' using errcode = 'P0001';\n  end if;\n\n  if v_txn.type = 'income' then\n    perform public.wallet_apply(v_txn.wallet_id, -v_txn.amount);\n  elsif v_txn.type = 'expense' then\n    perform public.wallet_apply(v_txn.wallet_id, v_txn.amount);\n  elsif v_txn.type = 'transfer' and v_txn.to_wallet_id is not null then\n    perform public.wallet_apply(\n      v_txn.wallet_id,\n      v_txn.amount + case when v_txn.service_fee_deducted then v_txn.service_fee else 0 end\n    );\n    perform public.wallet_apply(v_txn.to_wallet_id, -v_txn.amount);\n  end if;\n\n  delete from public.transactions where id = p_id;\nend;\n$$",
 "grant execute on function public.transactions_delete(uuid) to authenticated",
 "create or replace function public.bills_mark_paid(\n  p_id uuid,\n  p_paid_amount numeric default null,\n  p_paid_date timestamptz default null,\n  p_idempotency_key text default null\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_bill public.bills;\n  v_amount_paid numeric;\n  v_payment_date timestamptz;\n  v_wallet public.wallets;\n  v_payment_status bill_payment_status;\n  v_obligation public.obligations;\n  v_new_remaining numeric;\n  v_new_paid_installments integer;\n  v_new_obl_status obligation_status;\n  v_next_due_date timestamptz;\n  v_next_bill public.bills;\n  v_next_txn public.transactions;\nbegin\n  if p_idempotency_key is not null and exists (\n    select 1 from public.transactions\n    where owner_id = auth.uid()\n      and idempotency_key = p_idempotency_key\n      and created_at >= now() - interval '24 hours'\n      and status = 'completed'\n  ) then\n    return jsonb_build_object(\n      'id', p_id,\n      'message', 'Duplicate payment request detected. Original payment processed.'\n    );\n  end if;\n\n  select * into v_bill from public.bills where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Bill not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  v_amount_paid := coalesce(p_paid_amount, v_bill.amount);\n  v_payment_date := coalesce(p_paid_date, now());\n\n  if v_bill.wallet_id is not null then\n    select * into v_wallet from public.wallets where id = v_bill.wallet_id and owner_id = auth.uid();\n    if not found then\n      raise exception 'Linked wallet not found or inactive.' using errcode = 'P0002';\n    end if;\n\n    if not public.wallet_can_afford(v_wallet, v_amount_paid) then\n      if v_wallet.type::text = 'credit_card' then\n        raise exception 'This payment would go over the card''s credit limit.' using errcode = 'P0001';\n      end if;\n      raise exception 'Insufficient wallet balance to pay this bill.' using errcode = 'P0001';\n    end if;\n\n    perform public.wallet_apply(v_bill.wallet_id, -v_amount_paid);\n  end if;\n\n  if v_bill.pays_wallet_id is not null then\n    perform public.wallet_apply(v_bill.pays_wallet_id, v_amount_paid);\n  end if;\n\n  v_payment_status := case when v_amount_paid >= v_bill.amount then 'paid' else 'partial' end;\n\n  if v_bill.transaction_id is not null then\n    update public.transactions\n    set status = 'completed', amount = v_amount_paid, date = v_payment_date,\n        idempotency_key = coalesce(p_idempotency_key, idempotency_key)\n    where id = v_bill.transaction_id;\n  end if;\n\n  if v_bill.obligation_id is not null then\n    select * into v_obligation from public.obligations where id = v_bill.obligation_id;\n    if found and v_obligation.status not in ('settled', 'archived') then\n      v_new_remaining := round(greatest(0, v_obligation.remaining_balance - v_amount_paid)::numeric, 2);\n      v_new_paid_installments := case when v_obligation.is_installment\n        then v_obligation.paid_installments + 1 else v_obligation.paid_installments end;\n      v_new_obl_status := case\n        when v_new_remaining <= 0 then 'settled'\n        when v_new_paid_installments > 0 then 'partially_paid'\n        else 'active'\n      end;\n\n      update public.obligations\n      set remaining_balance = v_new_remaining,\n          paid_installments = v_new_paid_installments,\n          status = v_new_obl_status\n      where id = v_obligation.id;\n    end if;\n  end if;\n\n  if v_bill.is_recurring and v_bill.recurring_frequency is not null then\n    v_next_due_date := public.calculate_next_due_date(v_bill.due_date, v_bill.recurring_frequency);\n\n    insert into public.bills (\n      owner_id, name, amount, category_id, due_date, is_recurring, recurring_frequency,\n      wallet_id, reminder, reminder_days, notes, payment_status, status, parent_bill_id, type,\n      pays_wallet_id\n    ) values (\n      v_bill.owner_id, v_bill.name, v_bill.amount, v_bill.category_id, v_next_due_date,\n      v_bill.is_recurring, v_bill.recurring_frequency, v_bill.wallet_id, v_bill.reminder,\n      v_bill.reminder_days, v_bill.notes, 'unpaid', 'active',\n      coalesce(v_bill.parent_bill_id, v_bill.id), v_bill.type,\n      v_bill.pays_wallet_id\n    )\n    returning * into v_next_bill;\n\n    if v_bill.wallet_id is not null then\n      insert into public.transactions (\n        owner_id, wallet_id, category_id, amount, type, description, date,\n        attachments, tags, bill_id, status\n      ) values (\n        v_bill.owner_id, v_bill.wallet_id, v_bill.category_id, v_bill.amount, 'expense',\n        format('Bill: %s', v_bill.name), v_next_due_date, '{}', '{}', v_next_bill.id, 'pending'\n      )\n      returning * into v_next_txn;\n\n      update public.bills set transaction_id = v_next_txn.id where id = v_next_bill.id;\n    end if;\n  end if;\n\n  update public.bills\n  set paid_amount = v_amount_paid, last_paid_date = v_payment_date, payment_status = v_payment_status\n  where id = p_id;\n\n  return jsonb_build_object(\n    'billId', p_id,\n    'amountPaid', v_amount_paid,\n    'nextDueDate', v_next_due_date,\n    'isRecurring', v_bill.is_recurring\n  );\nend;\n$$",
 "grant execute on function public.bills_mark_paid(uuid, numeric, timestamptz, text) to authenticated",
 "create or replace function public.bills_summary()\nreturns jsonb\nlanguage plpgsql\nstable\nas $$\ndeclare\n  v_total_bills integer;\n  v_paid_bills integer;\n  v_unpaid_bills integer;\n  v_overdue_bills integer;\n  v_partial_bills integer;\n  v_recurring_bills integer;\n  v_total_amount_due numeric;\n  v_upcoming_amount numeric;\n  v_overdue_amount numeric;\n  v_total_wallet_balance numeric;\nbegin\n  select\n    count(*),\n    count(*) filter (where payment_status = 'paid'),\n    count(*) filter (where payment_status = 'unpaid'),\n    count(*) filter (where payment_status = 'overdue'),\n    count(*) filter (where payment_status = 'partial'),\n    count(*) filter (where is_recurring)\n  into v_total_bills, v_paid_bills, v_unpaid_bills, v_overdue_bills, v_partial_bills, v_recurring_bills\n  from public.bills\n  where owner_id = auth.uid() and status = 'active';\n\n  select\n    coalesce(sum(amount), 0),\n    coalesce(sum(amount) filter (where due_date > now()), 0),\n    coalesce(sum(amount) filter (where due_date < now()), 0)\n  into v_total_amount_due, v_upcoming_amount, v_overdue_amount\n  from public.bills\n  where owner_id = auth.uid() and status = 'active'\n    and payment_status in ('unpaid', 'overdue', 'partial');\n\n  select coalesce(sum(case when type::text = 'credit_card' then -balance else balance end), 0)\n  into v_total_wallet_balance\n  from public.wallets where owner_id = auth.uid() and status = 'active';\n\n  return jsonb_build_object(\n    'totalBills', v_total_bills,\n    'paidBills', v_paid_bills,\n    'unpaidBills', v_unpaid_bills,\n    'overdueBills', v_overdue_bills,\n    'partialBills', v_partial_bills,\n    'recurringBills', v_recurring_bills,\n    'totalAmountDue', v_total_amount_due,\n    'upcomingAmount', v_upcoming_amount,\n    'overdueAmount', v_overdue_amount,\n    'totalWalletBalance', v_total_wallet_balance,\n    'disposableIncome', v_total_wallet_balance - v_total_amount_due,\n    'summary', jsonb_build_object(\n      'message', format('You have %s unpaid bills totaling ₱%s',\n        v_unpaid_bills + v_overdue_bills, to_char(v_total_amount_due, 'FM999999990.00'))\n    )\n  );\nend;\n$$",
 "grant execute on function public.bills_summary() to authenticated",
 "create or replace function public.cards_sync_bills()\nreturns integer\nlanguage plpgsql\nas $$\ndeclare\n  c record;\n  v_due timestamptz;\n  v_source uuid;\n  v_open public.bills;\n  v_touched integer := 0;\nbegin\n  for c in\n    select * from public.wallets\n    where owner_id = auth.uid() and type::text = 'credit_card' and status = 'active' and due_day is not null\n  loop\n    v_due := (date_trunc('month', current_date) + ((c.due_day - 1) * interval '1 day'))::timestamptz;\n    if v_due::date < current_date then\n      v_due := v_due + interval '1 month';\n    end if;\n\n    select * into v_open from public.bills\n    where owner_id = auth.uid() and pays_wallet_id = c.id\n      and payment_status in ('unpaid', 'overdue', 'partial') and status = 'active'\n    order by due_date limit 1;\n\n    if found then\n      if c.balance <= 0 then\n        update public.bills set status = 'archived' where id = v_open.id;\n      elsif v_open.amount <> c.balance then\n        update public.bills set amount = c.balance where id = v_open.id;\n      end if;\n      v_touched := v_touched + 1;\n    elsif c.balance > 0 then\n      -- Default to paying from the richest non-card wallet; the user can change it on the bill.\n      select id into v_source from public.wallets\n      where owner_id = auth.uid() and status = 'active' and type::text <> 'credit_card'\n      order by balance desc limit 1;\n\n      insert into public.bills (\n        owner_id, type, name, amount, due_date, is_recurring, wallet_id, pays_wallet_id,\n        reminder, reminder_days, payment_status, status, notes\n      ) values (\n        auth.uid(), 'bill', c.name || ' payment', c.balance, v_due, false, v_source, c.id,\n        true, 3, 'unpaid', 'active', 'Credit card payment. The amount follows what you currently owe on the card.'\n      );\n      v_touched := v_touched + 1;\n    end if;\n  end loop;\n\n  return v_touched;\nend;\n$$",
 "grant execute on function public.cards_sync_bills() to authenticated",
 "create or replace function public.obligations_create(\n  p_direction obligation_direction,\n  p_name text,\n  p_counterparty text,\n  p_principal_amount numeric,\n  p_start_date timestamptz,\n  p_counterparty_contact text default null,\n  p_currency text default 'PHP',\n  p_interest_rate numeric default null,\n  p_interest_type interest_type default null,\n  p_due_date timestamptz default null,\n  p_wallet_id uuid default null,\n  p_category_id uuid default null,\n  p_notes text default null,\n  p_tags text[] default '{}',\n  p_is_installment boolean default false,\n  p_installment_amount numeric default null,\n  p_total_installments integer default null,\n  p_installment_frequency installment_frequency default null\n)\nreturns public.obligations\nlanguage plpgsql\nas $$\ndeclare\n  v_total_with_interest numeric;\n  v_obligation public.obligations;\n  v_wallet public.wallets;\n  v_disbursement_tx public.transactions;\n  v_due_dates timestamptz[];\n  v_due_date timestamptz;\n  v_bill public.bills;\n  v_txn public.transactions;\nbegin\n  if p_is_installment and (p_installment_amount is null or p_total_installments is null or p_installment_frequency is null) then\n    raise exception 'installmentAmount, totalInstallments, and installmentFrequency are required for installment obligations.'\n      using errcode = 'P0001';\n  end if;\n\n  v_total_with_interest := case when p_interest_rate is not null and p_interest_type is not null\n    then public.compute_total_with_interest(p_principal_amount, p_interest_rate, p_interest_type, p_start_date, p_due_date)\n    else null end;\n\n  if p_wallet_id is not null then\n    select * into v_wallet from public.wallets where id = p_wallet_id and owner_id = auth.uid() and status = 'active';\n    if not found then\n      raise exception 'Wallet not found.' using errcode = 'P0002';\n    end if;\n    -- Lending sends money out of the wallet.\n    if p_direction <> 'debt' and not public.wallet_can_afford(v_wallet, p_principal_amount) then\n      raise exception 'Insufficient wallet balance to lend this amount.' using errcode = 'P0001';\n    end if;\n  end if;\n\n  insert into public.obligations (\n    owner_id, direction, name, counterparty, counterparty_contact, principal_amount,\n    remaining_balance, currency, interest_rate, interest_type, total_with_interest,\n    start_date, due_date, wallet_id, category_id, notes, tags, status,\n    is_installment, installment_amount, total_installments, paid_installments, installment_frequency\n  ) values (\n    auth.uid(), p_direction, p_name, p_counterparty, p_counterparty_contact, p_principal_amount,\n    coalesce(v_total_with_interest, p_principal_amount), coalesce(p_currency, 'PHP'),\n    p_interest_rate, p_interest_type, v_total_with_interest,\n    p_start_date, p_due_date, p_wallet_id, p_category_id, p_notes, coalesce(p_tags, '{}'), 'active',\n    coalesce(p_is_installment, false), p_installment_amount, p_total_installments, 0, p_installment_frequency\n  )\n  returning * into v_obligation;\n\n  if p_wallet_id is not null then\n    perform public.wallet_apply(p_wallet_id, case when p_direction = 'debt' then p_principal_amount else -p_principal_amount end);\n\n    insert into public.transactions (\n      owner_id, wallet_id, category_id, amount, type, description, date, attachments, tags, status\n    ) values (\n      auth.uid(), p_wallet_id, p_category_id, p_principal_amount,\n      case when p_direction = 'debt' then 'income' else 'expense' end,\n      format('%s %s: %s', case when p_direction = 'debt' then 'Borrowed from' else 'Lent to' end, p_counterparty, p_name),\n      p_start_date, '{}', coalesce(p_tags, '{}'), 'completed'\n    )\n    returning * into v_disbursement_tx;\n\n    update public.obligations set disbursement_transaction_id = v_disbursement_tx.id where id = v_obligation.id;\n  end if;\n\n  if p_is_installment and p_installment_frequency is not null and p_installment_amount is not null and p_total_installments is not null then\n    v_due_dates := public.build_installment_dates(p_start_date, p_installment_frequency, p_total_installments);\n\n    foreach v_due_date in array v_due_dates loop\n      insert into public.bills (\n        owner_id, name, amount, category_id, due_date, is_recurring, type,\n        wallet_id, reminder, reminder_days, payment_status, status, obligation_id\n      ) values (\n        auth.uid(), p_name || ' — Installment', p_installment_amount, p_category_id, v_due_date, false,\n        case when p_direction = 'debt' then 'bill' else 'income' end,\n        p_wallet_id, true, 3, 'unpaid', 'active', v_obligation.id\n      )\n      returning * into v_bill;\n\n      if p_wallet_id is not null then\n        insert into public.transactions (\n          owner_id, wallet_id, category_id, amount, type, description, date,\n          attachments, tags, bill_id, status\n        ) values (\n          auth.uid(), p_wallet_id, p_category_id, p_installment_amount,\n          case when p_direction = 'debt' then 'expense' else 'income' end,\n          p_name || ' — Installment', v_due_date, '{}', coalesce(p_tags, '{}'), v_bill.id, 'pending'\n        )\n        returning * into v_txn;\n\n        update public.bills set transaction_id = v_txn.id where id = v_bill.id;\n      end if;\n    end loop;\n  end if;\n\n  select * into v_obligation from public.obligations where id = v_obligation.id;\n  return v_obligation;\nend;\n$$",
 "grant execute on function public.obligations_create(\n  obligation_direction, text, text, numeric, timestamptz, text, text, numeric, interest_type,\n  timestamptz, uuid, uuid, text, text[], boolean, numeric, integer, installment_frequency\n) to authenticated",
 "create or replace function public.obligations_record_payment(\n  p_id uuid,\n  p_amount numeric,\n  p_wallet_id uuid,\n  p_date timestamptz default null,\n  p_notes text default null,\n  p_idempotency_key text default null\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_obligation public.obligations;\n  v_wallet public.wallets;\n  v_payment_date timestamptz;\n  v_transaction_type transaction_type;\n  v_new_remaining numeric;\n  v_new_status obligation_status;\n  v_unpaid_bill public.bills;\nbegin\n  if p_idempotency_key is not null and exists (\n    select 1 from public.transactions\n    where owner_id = auth.uid() and idempotency_key = p_idempotency_key\n      and created_at >= now() - interval '24 hours' and status = 'completed'\n  ) then\n    return jsonb_build_object('id', p_id, 'message', 'Payment already recorded (cached).');\n  end if;\n\n  select * into v_obligation from public.obligations where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Obligation not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  if v_obligation.status in ('settled', 'archived') then\n    raise exception 'Cannot record payment on a % obligation.', v_obligation.status using errcode = 'P0001';\n  end if;\n\n  v_transaction_type := case when v_obligation.direction = 'debt' then 'expense' else 'income' end;\n\n  select * into v_wallet from public.wallets where id = p_wallet_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Wallet not found.' using errcode = 'P0002';\n  end if;\n\n  -- Repaying a debt sends money out of the wallet.\n  if v_obligation.direction = 'debt' and not public.wallet_can_afford(v_wallet, p_amount) then\n    if v_wallet.type::text = 'credit_card' then\n      raise exception 'This payment would go over the card''s credit limit.' using errcode = 'P0001';\n    end if;\n    raise exception 'Insufficient wallet balance.' using errcode = 'P0001';\n  end if;\n\n  perform public.wallet_apply(p_wallet_id, case when v_obligation.direction = 'debt' then -p_amount else p_amount end);\n\n  v_payment_date := coalesce(p_date, now());\n\n  insert into public.transactions (\n    owner_id, wallet_id, amount, type, description, date, attachments, tags, status, idempotency_key\n  ) values (\n    auth.uid(), p_wallet_id, p_amount, v_transaction_type,\n    coalesce(p_notes, format('%s %s: %s',\n      case when v_obligation.direction = 'debt' then 'Repayment to' else 'Received from' end,\n      v_obligation.counterparty, v_obligation.name)),\n    v_payment_date, '{}', '{}', 'completed', p_idempotency_key\n  );\n\n  v_new_remaining := round(greatest(0, v_obligation.remaining_balance - p_amount)::numeric, 2);\n  v_new_status := case\n    when v_new_remaining <= 0 then 'settled'\n    when v_obligation.paid_installments > 0 or v_new_remaining < v_obligation.remaining_balance then 'partially_paid'\n    else 'active'\n  end;\n\n  update public.obligations set remaining_balance = v_new_remaining, status = v_new_status where id = p_id;\n\n  if v_obligation.is_installment then\n    select * into v_unpaid_bill from public.bills\n    where obligation_id = v_obligation.id and payment_status = 'unpaid' and status = 'active'\n    order by due_date asc limit 1;\n\n    if found then\n      update public.bills\n      set payment_status = case when p_amount >= v_unpaid_bill.amount then 'paid' else 'partial' end,\n          paid_amount = p_amount, last_paid_date = v_payment_date\n      where id = v_unpaid_bill.id;\n\n      if v_unpaid_bill.transaction_id is not null then\n        update public.transactions\n        set status = 'completed', amount = p_amount, date = v_payment_date\n        where id = v_unpaid_bill.transaction_id;\n      end if;\n\n      update public.obligations set paid_installments = paid_installments + 1 where id = v_obligation.id;\n    end if;\n  end if;\n\n  return jsonb_build_object('remainingBalance', v_new_remaining, 'status', v_new_status);\nend;\n$$",
 "grant execute on function public.obligations_record_payment(uuid, numeric, uuid, timestamptz, text, text) to authenticated",
 "create or replace function public.investments_create(\n  p_name text,\n  p_type investment_type,\n  p_principal_amount numeric,\n  p_start_date timestamptz,\n  p_currency text default 'PHP',\n  p_platform text default null,\n  p_wallet_id uuid default null,\n  p_category_id uuid default null,\n  p_maturity_date timestamptz default null,\n  p_expected_return_rate numeric default null,\n  p_notes text default null,\n  p_tags text[] default '{}'\n)\nreturns public.investments\nlanguage plpgsql\nas $$\ndeclare\n  v_investment public.investments;\n  v_wallet public.wallets;\n  v_funding_tx public.transactions;\nbegin\n  if p_wallet_id is not null then\n    select * into v_wallet from public.wallets where id = p_wallet_id and owner_id = auth.uid() and status = 'active';\n    if not found then\n      raise exception 'Wallet not found.' using errcode = 'P0002';\n    end if;\n    if not public.wallet_can_afford(v_wallet, p_principal_amount) then\n      if v_wallet.type::text = 'credit_card' then\n        raise exception 'This would go over the card''s credit limit.' using errcode = 'P0001';\n      end if;\n      raise exception 'Insufficient wallet balance to fund this investment.' using errcode = 'P0001';\n    end if;\n  end if;\n\n  insert into public.investments (\n    owner_id, name, type, principal_amount, current_value, currency, platform,\n    wallet_id, category_id, start_date, maturity_date, expected_return_rate,\n    dividends_received, notes, tags, status\n  ) values (\n    auth.uid(), p_name, p_type, p_principal_amount, p_principal_amount, coalesce(p_currency, 'PHP'), p_platform,\n    p_wallet_id, p_category_id, p_start_date, p_maturity_date, p_expected_return_rate,\n    0, p_notes, coalesce(p_tags, '{}'), 'active'\n  )\n  returning * into v_investment;\n\n  insert into public.investment_value_snapshots (investment_id, value, snapshot_date)\n  values (v_investment.id, p_principal_amount, p_start_date);\n\n  if p_wallet_id is not null then\n    perform public.wallet_apply(p_wallet_id, -p_principal_amount);\n\n    insert into public.transactions (\n      owner_id, wallet_id, category_id, amount, type, description, date, attachments, tags, status\n    ) values (\n      auth.uid(), p_wallet_id, p_category_id, p_principal_amount, 'expense',\n      format('Investment: %s (%s)', p_name, p_type), p_start_date, '{}', coalesce(p_tags, '{}'), 'completed'\n    )\n    returning * into v_funding_tx;\n\n    update public.investments set funding_transaction_id = v_funding_tx.id where id = v_investment.id;\n  end if;\n\n  select * into v_investment from public.investments where id = v_investment.id;\n  return v_investment;\nend;\n$$",
 "grant execute on function public.investments_create(\n  text, investment_type, numeric, timestamptz, text, text, uuid, uuid, timestamptz, numeric, text, text[]\n) to authenticated",
 "create or replace function public.investments_record_return(\n  p_id uuid,\n  p_amount numeric,\n  p_wallet_id uuid,\n  p_date timestamptz default null,\n  p_notes text default null\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_investment public.investments;\n  v_return_date timestamptz := coalesce(p_date, now());\n  v_new_dividends numeric;\nbegin\n  select * into v_investment from public.investments where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Investment not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  perform public.wallet_apply(p_wallet_id, p_amount);\n\n  insert into public.transactions (\n    owner_id, wallet_id, category_id, amount, type, description, date, attachments, tags, status\n  ) values (\n    auth.uid(), p_wallet_id, v_investment.category_id, p_amount, 'income',\n    coalesce(p_notes, format('Investment return: %s', v_investment.name)),\n    v_return_date, '{}', v_investment.tags, 'completed'\n  );\n\n  update public.investments set dividends_received = dividends_received + p_amount\n  where id = p_id\n  returning dividends_received into v_new_dividends;\n\n  return jsonb_build_object('amount', p_amount, 'dividendsReceived', v_new_dividends);\nend;\n$$",
 "grant execute on function public.investments_record_return(uuid, numeric, uuid, timestamptz, text) to authenticated",
 "create or replace function public.investments_sell(\n  p_id uuid,\n  p_sale_amount numeric,\n  p_wallet_id uuid,\n  p_date timestamptz default null,\n  p_notes text default null\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_investment public.investments;\n  v_sale_date timestamptz := coalesce(p_date, now());\n  v_gain_loss numeric;\nbegin\n  select * into v_investment from public.investments where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Investment not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  if v_investment.status in ('sold', 'archived') then\n    raise exception 'Cannot sell a % investment.', v_investment.status using errcode = 'P0001';\n  end if;\n\n  v_gain_loss := round((p_sale_amount - v_investment.principal_amount)::numeric, 2);\n\n  perform public.wallet_apply(p_wallet_id, p_sale_amount);\n\n  insert into public.transactions (\n    owner_id, wallet_id, category_id, amount, type, description, date, attachments, tags, status\n  ) values (\n    auth.uid(), p_wallet_id, v_investment.category_id, p_sale_amount, 'income',\n    coalesce(p_notes, format('Sale of investment: %s', v_investment.name)),\n    v_sale_date, '{}', v_investment.tags, 'completed'\n  );\n\n  update public.investments set status = 'sold', current_value = p_sale_amount where id = p_id;\n\n  insert into public.investment_value_snapshots (investment_id, value, snapshot_date, notes)\n  values (p_id, p_sale_amount, v_sale_date, coalesce(p_notes, 'Sold'));\n\n  return jsonb_build_object('saleAmount', p_sale_amount, 'gainLoss', v_gain_loss);\nend;\n$$",
 "grant execute on function public.investments_sell(uuid, numeric, uuid, timestamptz, text) to authenticated",
 "create or replace function public.obligations_create(\n  p_direction obligation_direction,\n  p_name text,\n  p_counterparty text,\n  p_principal_amount numeric,\n  p_start_date timestamptz,\n  p_counterparty_contact text default null,\n  p_currency text default 'PHP',\n  p_interest_rate numeric default null,\n  p_interest_type interest_type default null,\n  p_due_date timestamptz default null,\n  p_wallet_id uuid default null,\n  p_category_id uuid default null,\n  p_notes text default null,\n  p_tags text[] default '{}',\n  p_is_installment boolean default false,\n  p_installment_amount numeric default null,\n  p_total_installments integer default null,\n  p_installment_frequency installment_frequency default null\n)\nreturns public.obligations\nlanguage plpgsql\nas $$\ndeclare\n  v_total_with_interest numeric;\n  v_obligation public.obligations;\n  v_wallet public.wallets;\n  v_disbursement_tx public.transactions;\n  v_due_dates timestamptz[];\n  v_due_date timestamptz;\n  v_bill public.bills;\n  v_txn public.transactions;\nbegin\n  if p_is_installment and (p_installment_amount is null or p_total_installments is null or p_installment_frequency is null) then\n    raise exception 'installmentAmount, totalInstallments, and installmentFrequency are required for installment obligations.'\n      using errcode = 'P0001';\n  end if;\n\n  v_total_with_interest := case when p_interest_rate is not null and p_interest_type is not null\n    then public.compute_total_with_interest(p_principal_amount, p_interest_rate, p_interest_type, p_start_date, p_due_date)\n    else null end;\n\n  if p_wallet_id is not null then\n    select * into v_wallet from public.wallets where id = p_wallet_id and owner_id = auth.uid() and status = 'active';\n    if not found then\n      raise exception 'Wallet not found.' using errcode = 'P0002';\n    end if;\n    -- Lending sends money out of the wallet.\n    if p_direction <> 'debt' and not public.wallet_can_afford(v_wallet, p_principal_amount) then\n      raise exception 'Insufficient wallet balance to lend this amount.' using errcode = 'P0001';\n    end if;\n  end if;\n\n  insert into public.obligations (\n    owner_id, direction, name, counterparty, counterparty_contact, principal_amount,\n    remaining_balance, currency, interest_rate, interest_type, total_with_interest,\n    start_date, due_date, wallet_id, category_id, notes, tags, status,\n    is_installment, installment_amount, total_installments, paid_installments, installment_frequency\n  ) values (\n    auth.uid(), p_direction, p_name, p_counterparty, p_counterparty_contact, p_principal_amount,\n    coalesce(v_total_with_interest, p_principal_amount), coalesce(p_currency, 'PHP'),\n    p_interest_rate, p_interest_type, v_total_with_interest,\n    p_start_date, p_due_date, p_wallet_id, p_category_id, p_notes, coalesce(p_tags, '{}'), 'active',\n    coalesce(p_is_installment, false), p_installment_amount, p_total_installments, 0, p_installment_frequency\n  )\n  returning * into v_obligation;\n\n  if p_wallet_id is not null then\n    perform public.wallet_apply(p_wallet_id, case when p_direction = 'debt' then p_principal_amount else -p_principal_amount end);\n\n    insert into public.transactions (\n      owner_id, wallet_id, category_id, amount, type, description, date, attachments, tags, status\n    ) values (\n      auth.uid(), p_wallet_id, p_category_id, p_principal_amount,\n      (case when p_direction = 'debt' then 'income' else 'expense' end)::transaction_type,\n      format('%s %s: %s', case when p_direction = 'debt' then 'Borrowed from' else 'Lent to' end, p_counterparty, p_name),\n      p_start_date, '{}', coalesce(p_tags, '{}'), 'completed'\n    )\n    returning * into v_disbursement_tx;\n\n    update public.obligations set disbursement_transaction_id = v_disbursement_tx.id where id = v_obligation.id;\n  end if;\n\n  if p_is_installment and p_installment_frequency is not null and p_installment_amount is not null and p_total_installments is not null then\n    v_due_dates := public.build_installment_dates(p_start_date, p_installment_frequency, p_total_installments);\n\n    foreach v_due_date in array v_due_dates loop\n      insert into public.bills (\n        owner_id, name, amount, category_id, due_date, is_recurring, type,\n        wallet_id, reminder, reminder_days, payment_status, status, obligation_id\n      ) values (\n        auth.uid(), p_name || ' — Installment', p_installment_amount, p_category_id, v_due_date, false,\n        (case when p_direction = 'debt' then 'bill' else 'income' end)::bill_type,\n        p_wallet_id, true, 3, 'unpaid', 'active', v_obligation.id\n      )\n      returning * into v_bill;\n\n      if p_wallet_id is not null then\n        insert into public.transactions (\n          owner_id, wallet_id, category_id, amount, type, description, date,\n          attachments, tags, bill_id, status\n        ) values (\n          auth.uid(), p_wallet_id, p_category_id, p_installment_amount,\n          (case when p_direction = 'debt' then 'expense' else 'income' end)::transaction_type,\n          p_name || ' — Installment', v_due_date, '{}', coalesce(p_tags, '{}'), v_bill.id, 'pending'\n        )\n        returning * into v_txn;\n\n        update public.bills set transaction_id = v_txn.id where id = v_bill.id;\n      end if;\n    end loop;\n  end if;\n\n  select * into v_obligation from public.obligations where id = v_obligation.id;\n  return v_obligation;\nend;\n$$",
 "grant execute on function public.obligations_create(\n  obligation_direction, text, text, numeric, timestamptz, text, text, numeric, interest_type,\n  timestamptz, uuid, uuid, text, text[], boolean, numeric, integer, installment_frequency\n) to authenticated",
 "create or replace function public.block_expense_from_savings()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  v_wallet_type wallet_type;\nbegin\n  if new.type <> 'expense' then\n    return new;\n  end if;\n\n  if new.description like 'Service fee for transfer%' then\n    return new;\n  end if;\n\n  if tg_op = 'UPDATE' and old.type = new.type and old.wallet_id = new.wallet_id then\n    return new;\n  end if;\n\n  select type into v_wallet_type from public.wallets where id = new.wallet_id;\n\n  if v_wallet_type = 'savings' then\n    raise exception 'Savings wallets can''t pay directly. Transfer the money to another wallet first.'\n      using errcode = 'P0001';\n  end if;\n\n  return new;\nend;\n$$",
 "drop trigger if exists transactions_block_expense_from_savings on public.transactions",
 "create trigger transactions_block_expense_from_savings\n  before insert or update of type, wallet_id on public.transactions\n  for each row execute function public.block_expense_from_savings()",
 "alter table public.budgets add column category_ids uuid[] not null default '{}'",
 "update public.budgets set category_ids = array[category_id] where category_id is not null",
 "create index budgets_category_ids_idx on public.budgets using gin (category_ids)",
 "create or replace function public.budget_calculate_spent(\n  p_owner uuid,\n  p_category_ids uuid[],\n  p_start timestamptz,\n  p_end timestamptz\n)\nreturns numeric\nlanguage sql\nstable\nas $$\n  select coalesce(sum(amount), 0)\n  from public.transactions\n  where owner_id = p_owner\n    and type = 'expense'\n    and status = 'completed'\n    and date >= p_start and date <= p_end\n    and (coalesce(cardinality(p_category_ids), 0) = 0 or category_id = any(p_category_ids));\n$$",
 "create or replace function public.budget_categories_json(p_category_ids uuid[])\nreturns jsonb\nlanguage sql\nstable\nas $$\n  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'color', c.color, 'icon', c.icon)), '[]'::jsonb)\n  from public.categories c\n  where c.id = any(coalesce(p_category_ids, '{}'));\n$$",
 "grant execute on function public.budget_categories_json(uuid[]) to authenticated",
 "drop function if exists public.budgets_create(text, numeric, budget_period, timestamptz, uuid, timestamptz, numeric)",
 "create or replace function public.budgets_create(\n  p_name text,\n  p_amount numeric,\n  p_period budget_period,\n  p_start_date timestamptz,\n  p_category_id uuid default null,\n  p_end_date timestamptz default null,\n  p_alert_threshold numeric default 80,\n  p_category_ids uuid[] default null\n)\nreturns public.budgets\nlanguage plpgsql\nas $$\ndeclare\n  v_end timestamptz;\n  v_ids uuid[];\n  v_budget public.budgets;\nbegin\n  v_ids := coalesce(p_category_ids, case when p_category_id is null then '{}'::uuid[] else array[p_category_id] end);\n\n  v_end := coalesce(p_end_date, case p_period\n    when 'daily' then p_start_date + interval '1 day'\n    when 'weekly' then p_start_date + interval '7 days'\n    when 'monthly' then p_start_date + interval '1 month'\n    when 'yearly' then p_start_date + interval '1 year'\n  end);\n\n  insert into public.budgets (\n    owner_id, category_id, category_ids, name, amount, spent, period, start_date, end_date,\n    alert_threshold, status\n  ) values (\n    auth.uid(), v_ids[1], v_ids, p_name, p_amount, 0, p_period, p_start_date, v_end,\n    coalesce(p_alert_threshold, 80), 'active'\n  )\n  returning * into v_budget;\n\n  return v_budget;\nend;\n$$",
 "grant execute on function public.budgets_create(text, numeric, budget_period, timestamptz, uuid, timestamptz, numeric, uuid[]) to authenticated",
 "create or replace function public.budgets_list(\n  p_page integer default 0,\n  p_limit integer default 20,\n  p_category_id uuid default null,\n  p_period budget_period default null,\n  p_status budget_status default 'active'\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_total integer;\n  v_items jsonb;\nbegin\n  select count(*) into v_total\n  from public.budgets\n  where owner_id = auth.uid()\n    and (p_category_id is null or p_category_id = any(category_ids))\n    and (p_period is null or period = p_period)\n    and status = p_status;\n\n  with page as (\n    select * from public.budgets\n    where owner_id = auth.uid()\n      and (p_category_id is null or p_category_id = any(category_ids))\n      and (p_period is null or period = p_period)\n      and status = p_status\n    order by start_date desc\n    offset p_page * p_limit limit p_limit\n  ),\n  refreshed as (\n    update public.budgets b\n    set spent = public.budget_calculate_spent(b.owner_id, b.category_ids, b.start_date, b.end_date),\n        status = case\n          when public.budget_calculate_spent(b.owner_id, b.category_ids, b.start_date, b.end_date) >= b.amount\n          then 'exceeded' else b.status end\n    from page\n    where b.id = page.id\n    returning b.*\n  )\n  select coalesce(\n    jsonb_agg(to_jsonb(r) || jsonb_build_object('categories', public.budget_categories_json(r.category_ids))),\n    '[]'::jsonb\n  ) into v_items from refreshed r;\n\n  return jsonb_build_object(\n    'items', v_items,\n    'totalPages', ceil(v_total::numeric / greatest(p_limit, 1)),\n    'currentPage', p_page,\n    'totalItems', v_total\n  );\nend;\n$$",
 "create or replace function public.budgets_get_current(p_period budget_period default null)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_items jsonb;\nbegin\n  with current_budgets as (\n    select * from public.budgets\n    where owner_id = auth.uid()\n      and status in ('active', 'exceeded')\n      and start_date <= now() and end_date >= now()\n      and (p_period is null or period = p_period)\n  ),\n  refreshed as (\n    update public.budgets b\n    set spent = public.budget_calculate_spent(b.owner_id, b.category_ids, b.start_date, b.end_date),\n        status = case\n          when public.budget_calculate_spent(b.owner_id, b.category_ids, b.start_date, b.end_date) >= b.amount\n          then 'exceeded' else b.status end\n    from current_budgets\n    where b.id = current_budgets.id\n    returning b.*\n  )\n  select coalesce(\n    jsonb_agg(to_jsonb(r) || jsonb_build_object('categories', public.budget_categories_json(r.category_ids))),\n    '[]'::jsonb\n  ) into v_items from refreshed r;\n\n  return jsonb_build_object('items', v_items, 'totalBudgets', jsonb_array_length(v_items));\nend;\n$$",
 "create or replace function public.budgets_check_status(p_id uuid)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_budget public.budgets;\n  v_spent numeric;\n  v_remaining numeric;\n  v_percentage numeric;\n  v_is_over boolean;\n  v_is_near boolean;\nbegin\n  select * into v_budget from public.budgets where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Budget not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  v_spent := public.budget_calculate_spent(v_budget.owner_id, v_budget.category_ids, v_budget.start_date, v_budget.end_date);\n  v_remaining := v_budget.amount - v_spent;\n  v_percentage := case when v_budget.amount > 0 then (v_spent / v_budget.amount) * 100 else 0 end;\n  v_is_over := v_spent >= v_budget.amount;\n  v_is_near := v_percentage >= coalesce(v_budget.alert_threshold, 80);\n\n  update public.budgets\n  set spent = v_spent, status = case when v_is_over then 'exceeded' else status end\n  where id = p_id\n  returning * into v_budget;\n\n  return jsonb_build_object(\n    'budget', to_jsonb(v_budget),\n    'spent', v_spent,\n    'remaining', v_remaining,\n    'percentageUsed', round(v_percentage, 2),\n    'isOverBudget', v_is_over,\n    'isNearThreshold', v_is_near\n  );\nend;\n$$",
 "create or replace function public.budgets_rollover(p_budget_id uuid)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_budget public.budgets;\n  v_remaining numeric;\n  v_next_start timestamptz;\n  v_next_end timestamptz;\n  v_new_budget public.budgets;\nbegin\n  select * into v_budget from public.budgets where id = p_budget_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Budget not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  v_remaining := v_budget.amount - coalesce(v_budget.spent, 0);\n  if v_remaining <= 0 then\n    raise exception 'No remaining budget to rollover.' using errcode = 'P0001';\n  end if;\n\n  v_next_start := v_budget.end_date + interval '1 day';\n  v_next_end := case v_budget.period\n    when 'daily' then v_next_start + interval '1 day'\n    when 'weekly' then v_next_start + interval '7 days'\n    when 'monthly' then v_next_start + interval '1 month'\n    when 'yearly' then v_next_start + interval '1 year'\n  end;\n\n  insert into public.budgets (\n    owner_id, category_id, category_ids, name, amount, spent, period, start_date, end_date,\n    alert_threshold, status\n  ) values (\n    v_budget.owner_id, v_budget.category_id, v_budget.category_ids, v_budget.name || ' (Rolled Over)',\n    v_budget.amount + v_remaining, 0, v_budget.period, v_next_start, v_next_end,\n    v_budget.alert_threshold, 'active'\n  )\n  returning * into v_new_budget;\n\n  return jsonb_build_object(\n    'previousBudgetId', v_budget.id,\n    'newBudgetId', v_new_budget.id,\n    'rolledOverAmount', v_remaining,\n    'newBudgetAmount', v_new_budget.amount,\n    'previousPeriod', jsonb_build_object(\n      'startDate', v_budget.start_date, 'endDate', v_budget.end_date,\n      'spent', v_budget.spent, 'remaining', v_remaining\n    ),\n    'newPeriod', jsonb_build_object(\n      'startDate', v_next_start, 'endDate', v_next_end, 'budgetAmount', v_new_budget.amount\n    )\n  );\nend;\n$$",
 "create or replace function public.budgets_performance()\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_budgets jsonb;\n  v_total_budgeted numeric := 0;\n  v_total_spent numeric := 0;\n  v_first_start timestamptz;\n  v_first_end timestamptz;\n  v_days_elapsed integer;\n  v_days_remaining integer;\n  v_overall_burn_rate numeric;\nbegin\n  with current_budgets as (\n    select b.*,\n      (select string_agg(c.name, ', ' order by c.name) from public.categories c where c.id = any(b.category_ids)) as category_name\n    from public.budgets b\n    where b.owner_id = auth.uid()\n      and b.status in ('active', 'exceeded')\n      and b.start_date <= now() and b.end_date >= now()\n  ),\n  metrics as (\n    select\n      cb.id as budget_id, cb.name, coalesce(cb.category_name, 'All expenses') as category_name,\n      cb.amount,\n      public.budget_calculate_spent(cb.owner_id, cb.category_ids, cb.start_date, cb.end_date) as spent,\n      ceil(extract(epoch from (cb.end_date - cb.start_date)) / 86400)::integer as total_days,\n      ceil(extract(epoch from (now() - cb.start_date)) / 86400)::integer as days_elapsed,\n      cb.start_date, cb.end_date\n    from current_budgets cb\n  )\n  select\n    coalesce(jsonb_agg(jsonb_build_object(\n      'budgetId', budget_id, 'name', name, 'categoryName', category_name,\n      'amount', amount, 'spent', spent, 'remaining', amount - spent,\n      'percentageUsed', case when amount > 0 then (spent / amount) * 100 else 0 end,\n      'burnRate', round(case when total_days > 0 and days_elapsed > 0\n        then (spent / nullif((amount / total_days) * days_elapsed, 0)) * 100 else 0 end, 2),\n      'daysElapsed', days_elapsed, 'daysRemaining', total_days - days_elapsed,\n      'status', case\n        when total_days > 0 and days_elapsed > 0\n          and (spent / nullif((amount / total_days) * days_elapsed, 0)) * 100 > 100 then 'OverBudget'\n        when total_days > 0 and days_elapsed > 0\n          and (spent / nullif((amount / total_days) * days_elapsed, 0)) * 100 < 100 then 'UnderBudget'\n        else 'OnTrack' end\n    )), '[]'::jsonb),\n    coalesce(sum(amount), 0), coalesce(sum(spent), 0),\n    min(start_date), max(end_date)\n  into v_budgets, v_total_budgeted, v_total_spent, v_first_start, v_first_end\n  from metrics;\n\n  if v_first_start is null then\n    return jsonb_build_object(\n      'message', 'No active budgets for this period', 'budgets', '[]'::jsonb,\n      'overallBurnRate', 0, 'totalBudgeted', 0, 'totalSpent', 0, 'daysElapsed', 0, 'daysRemaining', 0\n    );\n  end if;\n\n  v_days_elapsed := ceil(extract(epoch from (now() - v_first_start)) / 86400);\n  v_days_remaining := ceil(extract(epoch from (v_first_end - v_first_start)) / 86400) - v_days_elapsed;\n  v_overall_burn_rate := case when v_total_budgeted > 0 then (v_total_spent / v_total_budgeted) * 100 else 0 end;\n\n  return jsonb_build_object(\n    'budgets', v_budgets,\n    'overallBurnRate', round(v_overall_burn_rate, 2),\n    'totalBudgeted', v_total_budgeted,\n    'totalSpent', v_total_spent,\n    'totalRemaining', v_total_budgeted - v_total_spent,\n    'daysElapsed', v_days_elapsed,\n    'daysRemaining', v_days_remaining,\n    'message', case when v_overall_burn_rate > 100\n      then format('⚠️ You are %s%% through your budgets. Slow down!', round(v_overall_burn_rate, 0))\n      else format('✓ You are %s%% through your budgets. On track!', round(v_overall_burn_rate, 0)) end\n  );\nend;\n$$",
 "create or replace function public.budgets_suggestions()\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_suggestions jsonb;\nbegin\n  with budgeted as (\n    select distinct unnest(category_ids) as category_id from public.budgets\n    where owner_id = auth.uid()\n  ),\n  spending as (\n    select t.category_id, c.name, c.icon, c.color,\n           sum(t.amount) as total, count(*) as cnt\n    from public.transactions t\n    join public.categories c on c.id = t.category_id\n    where t.owner_id = auth.uid()\n      and t.type = 'expense' and t.status = 'completed'\n      and t.date >= now() - interval '30 days' and t.date <= now()\n      and t.category_id is not null\n      and t.category_id not in (select category_id from budgeted)\n    group by t.category_id, c.name, c.icon, c.color\n    order by total desc\n    limit 5\n  )\n  select coalesce(jsonb_agg(jsonb_build_object(\n    'categoryId', category_id, 'categoryName', name, 'categoryIcon', icon, 'categoryColor', color,\n    'averageMonthlySpend', round(total / 30, 2),\n    'totalSpentIn30Days', total, 'transactionCount', cnt,\n    'suggestedBudget', ceil(total / 30 * 1.2)\n  )), '[]'::jsonb)\n  into v_suggestions\n  from spending;\n\n  return jsonb_build_object(\n    'suggestions', v_suggestions,\n    'message', case when jsonb_array_length(v_suggestions) > 0\n      then format('We found %s categories you spend on frequently. Create budgets to track them better!', jsonb_array_length(v_suggestions))\n      else 'No unbudgeted spending found in the last 30 days.' end,\n    'period', jsonb_build_object('startDate', now() - interval '30 days', 'endDate', now(), 'days', 30)\n  );\nend;\n$$",
 "create or replace function public.budgets_summary()\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_total integer;\n  v_active integer;\n  v_exceeded integer;\n  v_total_budgeted numeric := 0;\n  v_total_spent numeric := 0;\n  v_current_count integer;\n  r record;\nbegin\n  select count(*) into v_total from public.budgets where owner_id = auth.uid();\n  select count(*) into v_active from public.budgets where owner_id = auth.uid() and status = 'active';\n  select count(*) into v_exceeded from public.budgets where owner_id = auth.uid() and status = 'exceeded';\n\n  v_current_count := 0;\n  for r in\n    select * from public.budgets\n    where owner_id = auth.uid() and status in ('active', 'exceeded')\n      and start_date <= now() and end_date >= now()\n  loop\n    v_current_count := v_current_count + 1;\n    v_total_budgeted := v_total_budgeted + r.amount;\n    v_total_spent := v_total_spent + public.budget_calculate_spent(r.owner_id, r.category_ids, r.start_date, r.end_date);\n  end loop;\n\n  return jsonb_build_object(\n    'totalBudgets', v_total, 'activeBudgets', v_active, 'exceededBudgets', v_exceeded,\n    'currentBudgetsCount', v_current_count,\n    'totalBudgeted', v_total_budgeted, 'totalSpent', v_total_spent,\n    'totalRemaining', v_total_budgeted - v_total_spent\n  );\nend;\n$$",
 "create or replace function public.bills_reset_overdue_on_new_date()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if new.payment_status = 'overdue'\n     and new.due_date is distinct from old.due_date\n     and new.due_date >= date_trunc('day', now()) then\n    new.payment_status := case when coalesce(new.paid_amount, 0) > 0 then 'partial'::bill_payment_status else 'unpaid'::bill_payment_status end;\n  end if;\n  return new;\nend;\n$$",
 "create trigger bills_reset_overdue_on_new_date\n  before update of due_date on public.bills\n  for each row execute function public.bills_reset_overdue_on_new_date()",
 "update public.bills\nset payment_status = case when coalesce(paid_amount, 0) > 0 then 'partial'::bill_payment_status else 'unpaid'::bill_payment_status end\nwhere payment_status = 'overdue'\n  and status = 'active'\n  and due_date >= date_trunc('day', now())",
 "create or replace function public.budgets_list(\n  p_page integer default 0,\n  p_limit integer default 20,\n  p_category_id uuid default null,\n  p_period budget_period default null,\n  p_status budget_status default 'active'\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_total integer;\n  v_items jsonb;\nbegin\n  -- 'active' stands for \"live budgets\": active and exceeded alike.\n  select count(*) into v_total\n  from public.budgets\n  where owner_id = auth.uid()\n    and (p_category_id is null or p_category_id = any(category_ids))\n    and (p_period is null or period = p_period)\n    and (status = p_status or (p_status = 'active' and status = 'exceeded'));\n\n  with page as (\n    select * from public.budgets\n    where owner_id = auth.uid()\n      and (p_category_id is null or p_category_id = any(category_ids))\n      and (p_period is null or period = p_period)\n      and (status = p_status or (p_status = 'active' and status = 'exceeded'))\n    order by start_date desc\n    offset p_page * p_limit limit p_limit\n  ),\n  refreshed as (\n    update public.budgets b\n    set spent = public.budget_calculate_spent(b.owner_id, b.category_ids, b.start_date, b.end_date),\n        status = case\n          when b.status = 'archived' then b.status\n          when public.budget_calculate_spent(b.owner_id, b.category_ids, b.start_date, b.end_date) >= b.amount\n            then 'exceeded' else 'active' end\n    from page\n    where b.id = page.id\n    returning b.*\n  )\n  select coalesce(\n    jsonb_agg(to_jsonb(r) || jsonb_build_object('categories', public.budget_categories_json(r.category_ids))),\n    '[]'::jsonb\n  ) into v_items from refreshed r;\n\n  return jsonb_build_object(\n    'items', v_items,\n    'totalPages', ceil(v_total::numeric / greatest(p_limit, 1)),\n    'currentPage', p_page,\n    'totalItems', v_total\n  );\nend;\n$$",
 "create or replace function public.budgets_get_current(p_period budget_period default null)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_items jsonb;\nbegin\n  with current_budgets as (\n    select * from public.budgets\n    where owner_id = auth.uid()\n      and status in ('active', 'exceeded')\n      and start_date <= now() and end_date >= now()\n      and (p_period is null or period = p_period)\n  ),\n  refreshed as (\n    update public.budgets b\n    set spent = public.budget_calculate_spent(b.owner_id, b.category_ids, b.start_date, b.end_date),\n        status = case\n          when public.budget_calculate_spent(b.owner_id, b.category_ids, b.start_date, b.end_date) >= b.amount\n            then 'exceeded' else 'active' end\n    from current_budgets\n    where b.id = current_budgets.id\n    returning b.*\n  )\n  select coalesce(\n    jsonb_agg(to_jsonb(r) || jsonb_build_object('categories', public.budget_categories_json(r.category_ids))),\n    '[]'::jsonb\n  ) into v_items from refreshed r;\n\n  return jsonb_build_object('items', v_items, 'totalBudgets', jsonb_array_length(v_items));\nend;\n$$",
 "create or replace function public.budgets_check_status(p_id uuid)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_budget public.budgets;\n  v_spent numeric;\n  v_remaining numeric;\n  v_percentage numeric;\n  v_is_over boolean;\n  v_is_near boolean;\nbegin\n  select * into v_budget from public.budgets where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Budget not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  v_spent := public.budget_calculate_spent(v_budget.owner_id, v_budget.category_ids, v_budget.start_date, v_budget.end_date);\n  v_remaining := v_budget.amount - v_spent;\n  v_percentage := case when v_budget.amount > 0 then (v_spent / v_budget.amount) * 100 else 0 end;\n  v_is_over := v_spent >= v_budget.amount;\n  v_is_near := v_percentage >= coalesce(v_budget.alert_threshold, 80);\n\n  update public.budgets\n  set spent = v_spent,\n      status = case\n        when status = 'archived' then status\n        when v_is_over then 'exceeded' else 'active' end\n  where id = p_id\n  returning * into v_budget;\n\n  return jsonb_build_object(\n    'budget', to_jsonb(v_budget),\n    'spent', v_spent,\n    'remaining', v_remaining,\n    'percentageUsed', round(v_percentage, 2),\n    'isOverBudget', v_is_over,\n    'isNearThreshold', v_is_near\n  );\nend;\n$$",
 "create or replace function public.budgets_summary()\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_total integer;\n  v_active integer := 0;\n  v_exceeded integer := 0;\n  v_total_budgeted numeric := 0;\n  v_total_spent numeric := 0;\n  v_current_count integer := 0;\n  v_spent numeric;\n  r record;\nbegin\n  select count(*) into v_total from public.budgets where owner_id = auth.uid();\n\n  for r in\n    select * from public.budgets\n    where owner_id = auth.uid() and status in ('active', 'exceeded')\n  loop\n    v_spent := public.budget_calculate_spent(r.owner_id, r.category_ids, r.start_date, r.end_date);\n    if v_spent >= r.amount then\n      v_exceeded := v_exceeded + 1;\n    else\n      v_active := v_active + 1;\n    end if;\n\n    if r.start_date <= now() and r.end_date >= now() then\n      v_current_count := v_current_count + 1;\n      v_total_budgeted := v_total_budgeted + r.amount;\n      v_total_spent := v_total_spent + v_spent;\n    end if;\n  end loop;\n\n  return jsonb_build_object(\n    'totalBudgets', v_total, 'activeBudgets', v_active, 'exceededBudgets', v_exceeded,\n    'currentBudgetsCount', v_current_count,\n    'totalBudgeted', v_total_budgeted, 'totalSpent', v_total_spent,\n    'totalRemaining', v_total_budgeted - v_total_spent\n  );\nend;\n$$",
 "update public.budgets b\nset spent = public.budget_calculate_spent(b.owner_id, b.category_ids, b.start_date, b.end_date),\n    status = 'active'\nwhere b.status = 'exceeded'\n  and public.budget_calculate_spent(b.owner_id, b.category_ids, b.start_date, b.end_date) < b.amount",
 "alter table public.investments\n  add column coin_id text,\n  add column coin_symbol text,\n  add column quantity numeric(28, 10)",
 "create or replace function public.bills_mark_paid(\n  p_id uuid,\n  p_paid_amount numeric default null,\n  p_paid_date timestamptz default null,\n  p_idempotency_key text default null\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_bill public.bills;\n  v_amount_paid numeric;\n  v_payment_date timestamptz;\n  v_wallet public.wallets;\n  v_payment_status bill_payment_status;\n  v_txn_type transaction_type;\n  v_obligation public.obligations;\n  v_new_remaining numeric;\n  v_new_paid_installments integer;\n  v_new_obl_status obligation_status;\n  v_next_due_date timestamptz;\n  v_next_bill public.bills;\n  v_next_txn public.transactions;\nbegin\n  if p_idempotency_key is not null and exists (\n    select 1 from public.transactions\n    where owner_id = auth.uid()\n      and idempotency_key = p_idempotency_key\n      and created_at >= now() - interval '24 hours'\n      and status = 'completed'\n  ) then\n    return jsonb_build_object(\n      'id', p_id,\n      'message', 'Duplicate payment request detected. Original payment processed.'\n    );\n  end if;\n\n  select * into v_bill from public.bills where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Bill not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  v_amount_paid := coalesce(p_paid_amount, v_bill.amount);\n  v_payment_date := coalesce(p_paid_date, now());\n  v_txn_type := case when v_bill.type::text = 'income' then 'income' else 'expense' end;\n\n  if v_bill.wallet_id is not null then\n    select * into v_wallet from public.wallets where id = v_bill.wallet_id and owner_id = auth.uid();\n    if not found then\n      raise exception 'Linked wallet not found or inactive.' using errcode = 'P0002';\n    end if;\n\n    if v_bill.type::text = 'income' then\n      -- Income credits the wallet; no balance check.\n      perform public.wallet_apply(v_bill.wallet_id, v_amount_paid);\n    else\n      if not public.wallet_can_afford(v_wallet, v_amount_paid) then\n        if v_wallet.type::text = 'credit_card' then\n          raise exception 'This payment would go over the card''s credit limit.' using errcode = 'P0001';\n        end if;\n        raise exception 'Insufficient wallet balance to pay this bill.' using errcode = 'P0001';\n      end if;\n      perform public.wallet_apply(v_bill.wallet_id, -v_amount_paid);\n    end if;\n  end if;\n\n  if v_bill.pays_wallet_id is not null then\n    perform public.wallet_apply(v_bill.pays_wallet_id, v_amount_paid);\n  end if;\n\n  v_payment_status := case when v_amount_paid >= v_bill.amount then 'paid' else 'partial' end;\n\n  if v_bill.transaction_id is not null then\n    update public.transactions\n    set status = 'completed', amount = v_amount_paid, date = v_payment_date, type = v_txn_type,\n        idempotency_key = coalesce(p_idempotency_key, idempotency_key)\n    where id = v_bill.transaction_id;\n  end if;\n\n  if v_bill.obligation_id is not null then\n    select * into v_obligation from public.obligations where id = v_bill.obligation_id;\n    if found and v_obligation.status not in ('settled', 'archived') then\n      v_new_remaining := round(greatest(0, v_obligation.remaining_balance - v_amount_paid)::numeric, 2);\n      v_new_paid_installments := case when v_obligation.is_installment\n        then v_obligation.paid_installments + 1 else v_obligation.paid_installments end;\n      v_new_obl_status := case\n        when v_new_remaining <= 0 then 'settled'\n        when v_new_paid_installments > 0 then 'partially_paid'\n        else 'active'\n      end;\n\n      update public.obligations\n      set remaining_balance = v_new_remaining,\n          paid_installments = v_new_paid_installments,\n          status = v_new_obl_status\n      where id = v_obligation.id;\n    end if;\n  end if;\n\n  if v_bill.is_recurring and v_bill.recurring_frequency is not null then\n    v_next_due_date := public.calculate_next_due_date(v_bill.due_date, v_bill.recurring_frequency);\n\n    insert into public.bills (\n      owner_id, name, amount, category_id, due_date, is_recurring, recurring_frequency,\n      wallet_id, reminder, reminder_days, notes, payment_status, status, parent_bill_id, type,\n      pays_wallet_id\n    ) values (\n      v_bill.owner_id, v_bill.name, v_bill.amount, v_bill.category_id, v_next_due_date,\n      v_bill.is_recurring, v_bill.recurring_frequency, v_bill.wallet_id, v_bill.reminder,\n      v_bill.reminder_days, v_bill.notes, 'unpaid', 'active',\n      coalesce(v_bill.parent_bill_id, v_bill.id), v_bill.type,\n      v_bill.pays_wallet_id\n    )\n    returning * into v_next_bill;\n\n    if v_bill.wallet_id is not null then\n      insert into public.transactions (\n        owner_id, wallet_id, category_id, amount, type, description, date,\n        attachments, tags, bill_id, status\n      ) values (\n        v_bill.owner_id, v_bill.wallet_id, v_bill.category_id, v_bill.amount, v_txn_type,\n        format('Bill: %s', v_bill.name), v_next_due_date, '{}', '{}', v_next_bill.id, 'pending'\n      )\n      returning * into v_next_txn;\n\n      update public.bills set transaction_id = v_next_txn.id where id = v_next_bill.id;\n    end if;\n  end if;\n\n  update public.bills\n  set paid_amount = v_amount_paid, last_paid_date = v_payment_date, payment_status = v_payment_status\n  where id = p_id;\n\n  return jsonb_build_object(\n    'billId', p_id,\n    'amountPaid', v_amount_paid,\n    'nextDueDate', v_next_due_date,\n    'isRecurring', v_bill.is_recurring\n  );\nend;\n$$",
 "grant execute on function public.bills_mark_paid(uuid, numeric, timestamptz, text) to authenticated",
 "create or replace function public.bills_create(\n  p_name text,\n  p_amount numeric,\n  p_due_date timestamptz,\n  p_is_recurring boolean,\n  p_type bill_type,\n  p_category_id uuid default null,\n  p_recurring_frequency recurring_frequency default null,\n  p_wallet_id uuid default null,\n  p_reminder boolean default true,\n  p_reminder_days integer default 3,\n  p_notes text default null\n)\nreturns public.bills\nlanguage plpgsql\nas $$\ndeclare\n  v_bill public.bills;\n  v_txn public.transactions;\nbegin\n  if p_is_recurring and p_recurring_frequency is null then\n    raise exception 'Recurring frequency required for recurring bills.' using errcode = 'P0001';\n  end if;\n\n  insert into public.bills (\n    owner_id, name, amount, category_id, due_date, is_recurring, type,\n    recurring_frequency, wallet_id, reminder, reminder_days, notes,\n    payment_status, status\n  ) values (\n    auth.uid(), p_name, p_amount, p_category_id, p_due_date, p_is_recurring, p_type,\n    p_recurring_frequency, p_wallet_id, p_reminder, p_reminder_days, p_notes,\n    'unpaid', 'active'\n  )\n  returning * into v_bill;\n\n  if p_wallet_id is not null then\n    insert into public.transactions (\n      owner_id, wallet_id, category_id, amount, type, description, date,\n      attachments, tags, bill_id, status\n    ) values (\n      auth.uid(), p_wallet_id, p_category_id, p_amount,\n      case when p_type::text = 'income' then 'income'::transaction_type else 'expense'::transaction_type end,\n      format('Bill: %s', p_name), p_due_date, '{}', '{}', v_bill.id, 'pending'\n    )\n    returning * into v_txn;\n\n    update public.bills set transaction_id = v_txn.id where id = v_bill.id\n    returning * into v_bill;\n  end if;\n\n  return v_bill;\nend;\n$$",
 "grant execute on function public.bills_create(\n  text, numeric, timestamptz, boolean, bill_type, uuid, recurring_frequency, uuid, boolean, integer, text\n) to authenticated",
 "create or replace function public.bills_archive(p_id uuid)\nreturns void\nlanguage plpgsql\nas $$\ndeclare\n  v_bill public.bills;\n  v_paid numeric;\nbegin\n  select * into v_bill from public.bills where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Bill not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  v_paid := coalesce(v_bill.paid_amount, 0);\n\n  if v_bill.payment_status in ('paid', 'partial') and v_paid > 0 then\n    if v_bill.wallet_id is not null then\n      perform public.wallet_apply(\n        v_bill.wallet_id,\n        case when v_bill.type::text = 'income' then -v_paid else v_paid end\n      );\n    end if;\n    if v_bill.pays_wallet_id is not null then\n      perform public.wallet_apply(v_bill.pays_wallet_id, -v_paid);\n    end if;\n  end if;\n\n  if v_bill.transaction_id is not null then\n    update public.bills set transaction_id = null where id = p_id;\n    delete from public.transactions\n    where id = v_bill.transaction_id and owner_id = auth.uid();\n  end if;\n\n  update public.bills\n  set status = 'archived', payment_status = 'unpaid', paid_amount = 0, last_paid_date = null\n  where id = p_id;\nend;\n$$",
 "grant execute on function public.bills_archive(uuid) to authenticated",
 "create or replace function public.bills_mark_unpaid(p_id uuid)\nreturns void\nlanguage plpgsql\nas $$\ndeclare\n  v_bill public.bills;\n  v_paid numeric;\n  v_old_txn_id uuid;\n  v_new_txn public.transactions;\nbegin\n  -- Lock the row so a double-click can't refund twice.\n  select * into v_bill from public.bills where id = p_id and owner_id = auth.uid() for update;\n  if not found then\n    raise exception 'Bill not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  v_paid := coalesce(v_bill.paid_amount, 0);\n\n  if v_bill.payment_status in ('paid', 'partial') and v_paid > 0 then\n    if v_bill.wallet_id is not null then\n      perform public.wallet_apply(\n        v_bill.wallet_id,\n        case when v_bill.type::text = 'income' then -v_paid else v_paid end\n      );\n    end if;\n    if v_bill.pays_wallet_id is not null then\n      perform public.wallet_apply(v_bill.pays_wallet_id, -v_paid);\n    end if;\n\n    v_old_txn_id := v_bill.transaction_id;\n    if v_old_txn_id is not null then\n      update public.bills set transaction_id = null where id = p_id;\n      delete from public.transactions where id = v_old_txn_id and owner_id = auth.uid();\n    end if;\n\n    if v_bill.wallet_id is not null then\n      insert into public.transactions (\n        owner_id, wallet_id, category_id, amount, type, description, date,\n        attachments, tags, bill_id, status\n      ) values (\n        auth.uid(), v_bill.wallet_id, v_bill.category_id, v_bill.amount,\n        case when v_bill.type::text = 'income' then 'income'::transaction_type else 'expense'::transaction_type end,\n        format('Bill: %s', v_bill.name), v_bill.due_date, '{}', '{}', v_bill.id, 'pending'\n      )\n      returning * into v_new_txn;\n\n      update public.bills set transaction_id = v_new_txn.id where id = p_id;\n    end if;\n  end if;\n\n  update public.bills\n  set payment_status = 'unpaid', paid_amount = 0, last_paid_date = null\n  where id = p_id;\nend;\n$$",
 "grant execute on function public.bills_mark_unpaid(uuid) to authenticated",
 "create or replace function public.bills_archive(p_id uuid)\nreturns void\nlanguage plpgsql\nas $$\ndeclare\n  v_bill public.bills;\n  v_paid numeric;\nbegin\n  select * into v_bill from public.bills where id = p_id and owner_id = auth.uid() for update;\n  if not found then\n    raise exception 'Bill not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  v_paid := coalesce(v_bill.paid_amount, 0);\n\n  if v_bill.payment_status in ('paid', 'partial') and v_paid > 0 then\n    if v_bill.wallet_id is not null then\n      perform public.wallet_apply(\n        v_bill.wallet_id,\n        case when v_bill.type::text = 'income' then -v_paid else v_paid end\n      );\n    end if;\n    if v_bill.pays_wallet_id is not null then\n      perform public.wallet_apply(v_bill.pays_wallet_id, -v_paid);\n    end if;\n  end if;\n\n  if v_bill.transaction_id is not null then\n    update public.bills set transaction_id = null where id = p_id;\n    delete from public.transactions\n    where id = v_bill.transaction_id and owner_id = auth.uid();\n  end if;\n\n  update public.bills\n  set status = 'archived', payment_status = 'unpaid', paid_amount = 0, last_paid_date = null\n  where id = p_id;\nend;\n$$",
 "grant execute on function public.bills_archive(uuid) to authenticated",
 "create or replace function public.transactions_delete(p_id uuid)\nreturns void\nlanguage plpgsql\nas $$\ndeclare\n  v_txn public.transactions;\nbegin\n  select * into v_txn from public.transactions\n  where id = p_id and owner_id = auth.uid() for update;\n\n  if not found then\n    raise exception 'Transaction not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  if v_txn.status <> 'completed' then\n    raise exception 'Can only delete completed transactions.' using errcode = 'P0001';\n  end if;\n\n  if v_txn.type = 'income' then\n    perform public.wallet_apply(v_txn.wallet_id, -v_txn.amount);\n  elsif v_txn.type = 'expense' then\n    perform public.wallet_apply(v_txn.wallet_id, v_txn.amount);\n  elsif v_txn.type = 'transfer' and v_txn.to_wallet_id is not null then\n    perform public.wallet_apply(\n      v_txn.wallet_id,\n      v_txn.amount + case when v_txn.service_fee_deducted then v_txn.service_fee else 0 end\n    );\n    perform public.wallet_apply(v_txn.to_wallet_id, -v_txn.amount);\n  end if;\n\n  update public.bills\n  set transaction_id = null, payment_status = 'unpaid', paid_amount = 0, last_paid_date = null\n  where transaction_id = p_id and owner_id = auth.uid();\n\n  update public.obligations set disbursement_transaction_id = null\n  where disbursement_transaction_id = p_id and owner_id = auth.uid();\n\n  update public.investments set funding_transaction_id = null\n  where funding_transaction_id = p_id and owner_id = auth.uid();\n\n  delete from public.transactions where id = p_id;\nend;\n$$",
 "grant execute on function public.transactions_delete(uuid) to authenticated",
 "create or replace function public.bills_mark_paid(\n  p_id uuid,\n  p_paid_amount numeric default null,\n  p_paid_date timestamptz default null,\n  p_idempotency_key text default null\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_bill public.bills;\n  v_new_txn_id uuid;\n  v_amount_paid numeric;\n  v_payment_date timestamptz;\n  v_wallet public.wallets;\n  v_payment_status bill_payment_status;\n  v_txn_type transaction_type;\n  v_obligation public.obligations;\n  v_new_remaining numeric;\n  v_new_paid_installments integer;\n  v_new_obl_status obligation_status;\n  v_next_due_date timestamptz;\n  v_next_bill public.bills;\n  v_next_txn public.transactions;\nbegin\n  if p_idempotency_key is not null and exists (\n    select 1 from public.transactions\n    where owner_id = auth.uid()\n      and idempotency_key = p_idempotency_key\n      and created_at >= now() - interval '24 hours'\n      and status = 'completed'\n  ) then\n    return jsonb_build_object(\n      'id', p_id,\n      'message', 'Duplicate payment request detected. Original payment processed.'\n    );\n  end if;\n\n  select * into v_bill from public.bills where id = p_id and owner_id = auth.uid();\n  if not found then\n    raise exception 'Bill not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  v_amount_paid := coalesce(p_paid_amount, v_bill.amount);\n  v_payment_date := coalesce(p_paid_date, now());\n  v_txn_type := case when v_bill.type::text = 'income' then 'income' else 'expense' end;\n\n  if v_bill.wallet_id is not null then\n    select * into v_wallet from public.wallets where id = v_bill.wallet_id and owner_id = auth.uid();\n    if not found then\n      raise exception 'Linked wallet not found or inactive.' using errcode = 'P0002';\n    end if;\n\n    if v_bill.type::text = 'income' then\n      -- Income credits the wallet; no balance check.\n      perform public.wallet_apply(v_bill.wallet_id, v_amount_paid);\n    else\n      if not public.wallet_can_afford(v_wallet, v_amount_paid) then\n        if v_wallet.type::text = 'credit_card' then\n          raise exception 'This payment would go over the card''s credit limit.' using errcode = 'P0001';\n        end if;\n        raise exception 'Insufficient wallet balance to pay this bill.' using errcode = 'P0001';\n      end if;\n      perform public.wallet_apply(v_bill.wallet_id, -v_amount_paid);\n    end if;\n  end if;\n\n  if v_bill.pays_wallet_id is not null then\n    perform public.wallet_apply(v_bill.pays_wallet_id, v_amount_paid);\n  end if;\n\n  v_payment_status := case when v_amount_paid >= v_bill.amount then 'paid' else 'partial' end;\n\n  if v_bill.transaction_id is not null then\n    update public.transactions\n    set status = 'completed', amount = v_amount_paid, date = v_payment_date, type = v_txn_type,\n        idempotency_key = coalesce(p_idempotency_key, idempotency_key)\n    where id = v_bill.transaction_id;\n  elsif v_bill.wallet_id is not null then\n    insert into public.transactions (\n      owner_id, wallet_id, category_id, amount, type, description, date,\n      attachments, tags, bill_id, idempotency_key, status\n    ) values (\n      auth.uid(), v_bill.wallet_id, v_bill.category_id, v_amount_paid, v_txn_type,\n      format('Bill: %s', v_bill.name), v_payment_date, '{}', '{}', v_bill.id,\n      p_idempotency_key, 'completed'\n    )\n    returning id into v_new_txn_id;\n\n    update public.bills set transaction_id = v_new_txn_id where id = p_id;\n  end if;\n\n  if v_bill.obligation_id is not null then\n    select * into v_obligation from public.obligations where id = v_bill.obligation_id;\n    if found and v_obligation.status not in ('settled', 'archived') then\n      v_new_remaining := round(greatest(0, v_obligation.remaining_balance - v_amount_paid)::numeric, 2);\n      v_new_paid_installments := case when v_obligation.is_installment\n        then v_obligation.paid_installments + 1 else v_obligation.paid_installments end;\n      v_new_obl_status := case\n        when v_new_remaining <= 0 then 'settled'\n        when v_new_paid_installments > 0 then 'partially_paid'\n        else 'active'\n      end;\n\n      update public.obligations\n      set remaining_balance = v_new_remaining,\n          paid_installments = v_new_paid_installments,\n          status = v_new_obl_status\n      where id = v_obligation.id;\n    end if;\n  end if;\n\n  if v_bill.is_recurring and v_bill.recurring_frequency is not null then\n    v_next_due_date := public.calculate_next_due_date(v_bill.due_date, v_bill.recurring_frequency);\n\n    insert into public.bills (\n      owner_id, name, amount, category_id, due_date, is_recurring, recurring_frequency,\n      wallet_id, reminder, reminder_days, notes, payment_status, status, parent_bill_id, type,\n      pays_wallet_id\n    ) values (\n      v_bill.owner_id, v_bill.name, v_bill.amount, v_bill.category_id, v_next_due_date,\n      v_bill.is_recurring, v_bill.recurring_frequency, v_bill.wallet_id, v_bill.reminder,\n      v_bill.reminder_days, v_bill.notes, 'unpaid', 'active',\n      coalesce(v_bill.parent_bill_id, v_bill.id), v_bill.type,\n      v_bill.pays_wallet_id\n    )\n    returning * into v_next_bill;\n\n    if v_bill.wallet_id is not null then\n      insert into public.transactions (\n        owner_id, wallet_id, category_id, amount, type, description, date,\n        attachments, tags, bill_id, status\n      ) values (\n        v_bill.owner_id, v_bill.wallet_id, v_bill.category_id, v_bill.amount, v_txn_type,\n        format('Bill: %s', v_bill.name), v_next_due_date, '{}', '{}', v_next_bill.id, 'pending'\n      )\n      returning * into v_next_txn;\n\n      update public.bills set transaction_id = v_next_txn.id where id = v_next_bill.id;\n    end if;\n  end if;\n\n  update public.bills\n  set paid_amount = v_amount_paid, last_paid_date = v_payment_date, payment_status = v_payment_status\n  where id = p_id;\n\n  return jsonb_build_object(\n    'billId', p_id,\n    'amountPaid', v_amount_paid,\n    'nextDueDate', v_next_due_date,\n    'isRecurring', v_bill.is_recurring\n  );\nend;\n$$",
 "grant execute on function public.bills_mark_paid(uuid, numeric, timestamptz, text) to authenticated",
 "create or replace function public.bills_summary()\nreturns jsonb\nlanguage plpgsql\nstable\nas $$\ndeclare\n  v_total_bills integer;\n  v_paid_bills integer;\n  v_unpaid_bills integer;\n  v_overdue_bills integer;\n  v_partial_bills integer;\n  v_recurring_bills integer;\n  v_total_amount numeric;\n  v_paid_amount numeric;\n  v_unpaid_amount numeric;\n  v_total_amount_due numeric;\n  v_upcoming_amount numeric;\n  v_overdue_amount numeric;\n  v_total_wallet_balance numeric;\nbegin\n  select\n    count(*),\n    count(*) filter (where payment_status = 'paid'),\n    count(*) filter (where payment_status = 'unpaid'),\n    count(*) filter (where payment_status = 'overdue'),\n    count(*) filter (where payment_status = 'partial'),\n    count(*) filter (where is_recurring),\n    coalesce(sum(amount), 0),\n    coalesce(sum(coalesce(paid_amount, amount)) filter (where payment_status = 'paid'), 0),\n    coalesce(sum(amount - coalesce(paid_amount, 0)) filter (where payment_status in ('unpaid', 'overdue', 'partial')), 0)\n  into v_total_bills, v_paid_bills, v_unpaid_bills, v_overdue_bills, v_partial_bills, v_recurring_bills,\n       v_total_amount, v_paid_amount, v_unpaid_amount\n  from public.bills\n  where owner_id = auth.uid() and status = 'active';\n\n  select\n    coalesce(sum(amount), 0),\n    coalesce(sum(amount) filter (where due_date > now()), 0),\n    coalesce(sum(amount) filter (where due_date < now()), 0)\n  into v_total_amount_due, v_upcoming_amount, v_overdue_amount\n  from public.bills\n  where owner_id = auth.uid() and status = 'active'\n    and payment_status in ('unpaid', 'overdue', 'partial');\n\n  select coalesce(sum(case when type::text = 'credit_card' then -balance else balance end), 0)\n  into v_total_wallet_balance\n  from public.wallets where owner_id = auth.uid() and status = 'active';\n\n  return jsonb_build_object(\n    'totalBills', v_total_bills,\n    'paidBills', v_paid_bills,\n    'unpaidBills', v_unpaid_bills + v_overdue_bills + v_partial_bills,\n    'overdueBills', v_overdue_bills,\n    'partialBills', v_partial_bills,\n    'recurringBills', v_recurring_bills,\n    'totalAmount', v_total_amount,\n    'paidAmount', v_paid_amount,\n    'unpaidAmount', v_unpaid_amount,\n    'totalAmountDue', v_total_amount_due,\n    'upcomingAmount', v_upcoming_amount,\n    'overdueAmount', v_overdue_amount,\n    'totalWalletBalance', v_total_wallet_balance,\n    'disposableIncome', v_total_wallet_balance - v_total_amount_due,\n    'summary', jsonb_build_object(\n      'message', format('You have %s unpaid bills totaling ₱%s',\n        v_unpaid_bills + v_overdue_bills, to_char(v_total_amount_due, 'FM999999990.00'))\n    )\n  );\nend;\n$$",
 "grant execute on function public.bills_summary() to authenticated",
 "alter type recurring_frequency add value if not exists 'biweekly' after 'weekly'",
 "create or replace function public.calculate_next_due_date(\n  p_current timestamptz,\n  p_frequency recurring_frequency\n)\nreturns timestamptz\nlanguage sql\nimmutable\nas $$\n  select case p_frequency\n    when 'daily' then p_current + interval '1 day'\n    when 'weekly' then p_current + interval '7 days'\n    when 'biweekly' then p_current + interval '14 days'\n    when 'monthly' then p_current + interval '1 month'\n    when 'yearly' then p_current + interval '1 year'\n    else p_current\n  end;\n$$",
 "create table if not exists public.sync_applied_ops (\n  op_id uuid primary key,\n  owner_id uuid not null default auth.uid() references public.profiles(id) on delete cascade,\n  applied_at timestamptz not null default now()\n)",
 "alter table public.sync_applied_ops enable row level security",
 "drop policy if exists sync_applied_ops_select_own on public.sync_applied_ops",
 "create policy sync_applied_ops_select_own on public.sync_applied_ops\n  for select using (owner_id = auth.uid())",
 "drop policy if exists sync_applied_ops_insert_own on public.sync_applied_ops",
 "create policy sync_applied_ops_insert_own on public.sync_applied_ops\n  for insert with check (owner_id = auth.uid())",
 "create or replace function public.sync_use_client_id()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  v_ids jsonb := nullif(current_setting('app.client_ids', true), '')::jsonb;\n  v_pos integer := coalesce(nullif(current_setting('app.client_ids_pos', true), '')::integer, 0);\nbegin\n  if v_ids is not null and v_pos < jsonb_array_length(v_ids) then\n    new.id := (v_ids ->> v_pos)::uuid;\n    perform set_config('app.client_ids_pos', (v_pos + 1)::text, true);\n  end if;\n  return new;\nend;\n$$",
 "do $$\ndeclare\n  t text;\nbegin\n  foreach t in array array[\n    'wallets', 'categories', 'transactions', 'bills', 'budgets',\n    'obligations', 'investments', 'investment_value_snapshots'\n  ] loop\n    execute format('drop trigger if exists a_sync_use_client_id on public.%I', t);\n    execute format(\n      'create trigger a_sync_use_client_id before insert on public.%I for each row execute function public.sync_use_client_id()',\n      t\n    );\n  end loop;\nend;\n$$",
 "create or replace function public.sync_replay(\n  p_op_id uuid,\n  p_name text,\n  p_args jsonb default '{}'::jsonb,\n  p_ids jsonb default '[]'::jsonb\n)\nreturns jsonb\nlanguage plpgsql\nas $$\ndeclare\n  v_proc pg_proc;\n  v_parts text[] := '{}';\n  v_key text;\n  v_val jsonb;\n  v_idx integer;\n  v_type text;\n  v_expr text;\nbegin\n  if p_name !~ '^(wallets|categories|transactions|bills|budgets|obligations|investments|cards)_[a-z_]+$' then\n    raise exception 'Operation % can not be replayed.', p_name using errcode = '22023';\n  end if;\n\n  insert into public.sync_applied_ops (op_id) values (p_op_id) on conflict do nothing;\n  if not found then\n    return jsonb_build_object('duplicate', true);\n  end if;\n\n  -- The overload whose parameter names cover every supplied argument.\n  select p.* into v_proc\n  from pg_proc p\n  where p.pronamespace = 'public'::regnamespace\n    and p.proname = p_name\n    and not exists (\n      select 1 from jsonb_object_keys(coalesce(p_args, '{}'::jsonb)) k\n      where k <> all (coalesce(p.proargnames, '{}'::text[]))\n    )\n  order by p.pronargs desc\n  limit 1;\n\n  if not found then\n    raise exception 'No function % matches the queued arguments.', p_name using errcode = '42883';\n  end if;\n\n  perform set_config('app.client_ids', coalesce(p_ids, '[]'::jsonb)::text, true);\n  perform set_config('app.client_ids_pos', '0', true);\n\n  for v_key, v_val in select * from jsonb_each(coalesce(p_args, '{}'::jsonb)) loop\n    v_idx := array_position(v_proc.proargnames, v_key);\n    v_type := format_type((string_to_array(v_proc.proargtypes::text, ' '))[v_idx]::oid, null);\n    if jsonb_typeof(v_val) = 'null' then\n      v_expr := format('null::%s', v_type);\n    elsif v_type = 'jsonb' then\n      v_expr := format('($1 -> %L)', v_key);\n    elsif v_type like '%[]' then\n      v_expr := format('array(select jsonb_array_elements_text($1 -> %L))::%s', v_key, v_type);\n    else\n      v_expr := format('($1 ->> %L)::%s', v_key, v_type);\n    end if;\n    v_parts := v_parts || format('%I => %s', v_key, v_expr);\n  end loop;\n\n  execute format('select public.%I(%s)', p_name, array_to_string(v_parts, ', ')) using coalesce(p_args, '{}'::jsonb);\n\n  return jsonb_build_object('applied', true);\nend;\n$$",
 "grant execute on function public.sync_replay(uuid, text, jsonb, jsonb) to authenticated",
 "alter table public.transactions\n  add column if not exists exclude_from_baseline boolean not null default false",
 "alter table public.profiles\n  add column if not exists baseline_excluded_category_ids uuid[] not null default '{}'",
 "drop function if exists public.transactions_update(uuid, uuid, text, timestamptz, text[], text[], transaction_status)",
 "create or replace function public.transactions_update(\n  p_id uuid,\n  p_category_id uuid default null,\n  p_description text default null,\n  p_date timestamptz default null,\n  p_attachments text[] default null,\n  p_tags text[] default null,\n  p_status transaction_status default null,\n  p_exclude_from_baseline boolean default null\n)\nreturns public.transactions\nlanguage plpgsql\nas $$\ndeclare\n  v_txn public.transactions;\nbegin\n  update public.transactions\n  set\n    category_id = coalesce(p_category_id, category_id),\n    description = coalesce(p_description, description),\n    date = coalesce(p_date, date),\n    attachments = coalesce(p_attachments, attachments),\n    tags = coalesce(p_tags, tags),\n    status = coalesce(p_status, status),\n    exclude_from_baseline = coalesce(p_exclude_from_baseline, exclude_from_baseline)\n  where id = p_id and owner_id = auth.uid()\n  returning * into v_txn;\n\n  if not found then\n    raise exception 'Transaction not found or you do not have permission.' using errcode = 'P0002';\n  end if;\n\n  return v_txn;\nend;\n$$",
 "grant execute on function public.transactions_update(uuid, uuid, text, timestamptz, text[], text[], transaction_status, boolean) to authenticated",
 "create or replace function public.categories_set_exclude_from_baseline(\n  p_id uuid,\n  p_exclude boolean\n)\nreturns uuid[]\nlanguage plpgsql\nas $$\ndeclare\n  v_ids uuid[];\nbegin\n  if not exists (\n    select 1 from public.categories\n    where id = p_id and (owner_id = auth.uid() or owner_id is null)\n  ) then\n    raise exception 'Category not found.' using errcode = 'P0002';\n  end if;\n\n  update public.profiles\n  set baseline_excluded_category_ids = case\n    when p_exclude then array(select distinct unnest(array_append(baseline_excluded_category_ids, p_id)))\n    else array_remove(baseline_excluded_category_ids, p_id)\n  end\n  where id = auth.uid()\n  returning baseline_excluded_category_ids into v_ids;\n\n  return v_ids;\nend;\n$$",
 "grant execute on function public.categories_set_exclude_from_baseline(uuid, boolean) to authenticated",
 "do $$\ndeclare\n  v_uid text;\nbegin\n  if not exists (select 1 from pg_roles where rolname = 'fico_readonly') then\n    return;\n  end if;\n  select substring(pg_get_expr(p.polqual, p.polrelid) from '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')\n    into v_uid\n  from pg_policy p\n  where p.polname = 'fico_mcp_read' and p.polrelid = 'public.wallets'::regclass;\n  if v_uid is null or exists (\n    select 1 from pg_policy where polname = 'fico_mcp_read' and polrelid = 'public.profiles'::regclass\n  ) then\n    return;\n  end if;\n  execute format('create policy fico_mcp_read on public.profiles for select to fico_readonly using (id = %L)', v_uid);\nend;\n$$"
